// ---------- small helpers ----------
const nn = v => (v === undefined ? null : (typeof v === 'boolean' ? (v ? 1 : 0) : v));
function db(env) {
  const D = env.DB;
  const st = (sql, a) => D.prepare(sql).bind(...a.map(nn));
  return {
    all: async (sql, ...a) => (await st(sql, a).all()).results || [],
    one: async (sql, ...a) => (await st(sql, a).first()) || null,
    run: async (sql, ...a) => (await st(sql, a).run()).meta || {},
    stmt: (sql, ...a) => st(sql, a),
    batch: async (stmts) => { for (let i = 0; i < stmts.length; i += 80) await D.batch(stmts.slice(i, i + 80)); },
    DB_batch_all: async (stmts) => { if (stmts.length) await D.batch(stmts); },
  };
}
const J = (data, status = 200, headers = {}) => { if (typeof MCTX !== 'undefined' && MCTX.notes26 && MCTX.notes26.length && data && typeof data === 'object' && !Array.isArray(data)) { data = { ...data, _notes: MCTX.notes26 }; MCTX.notes26 = []; } return J0(data, status, headers); };
const J0 = (data, status = 200, headers = {}) => new Response(JSON.stringify(data), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers } });
const ERR = (msg, status = 400) => J({ error: msg }, status);
class HttpError extends Error { constructor(msg, status = 400) { super(msg); this.status = status; } }
const need = (cond, msg, status = 400) => { if (!cond) throw new HttpError(msg, status); };
const cents = v => { const n = Math.round(parseFloat(String(v).replace(/[$,\s]/g, '')) * 100); return Number.isFinite(n) ? n : NaN; };
const enc = s => new TextEncoder().encode(s);
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
const unhex = h => new Uint8Array(h.match(/../g).map(x => parseInt(x, 16)));
const randHex = n => hex(crypto.getRandomValues(new Uint8Array(n)));
async function hashPw(pw, salt) {
  const key = await crypto.subtle.importKey('raw', enc(pw), 'PBKDF2', false, ['deriveBits']);
  return hex(await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: unhex(salt), iterations: 100000 }, key, 256));
}
let TODAY_OVERRIDE = null; // test hook: set only by the local dev harness (env.PM_TODAY); never set in production
function todayNY() { if (TODAY_OVERRIDE) return TODAY_OVERRIDE; return new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()); }
const nowISO = () => new Date().toISOString();
const ym = d => d.slice(0, 7);
function addMonths(ymStr, n) { let [y, m] = ymStr.split('-').map(Number); m += n; while (m > 12) { m -= 12; y++; } while (m < 1) { m += 12; y--; } return `${y}-${String(m).padStart(2, '0')}`; }
function addDays(d, n) { const t = new Date(d + 'T12:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); }
const daysBetween = (a, b) => Math.round((new Date(b + 'T12:00:00Z') - new Date(a + 'T12:00:00Z')) / 86400000);
const monthEnd = ymStr => { const [y, m] = ymStr.split('-').map(Number); return `${ymStr}-${String(new Date(Date.UTC(y, m, 0)).getUTCDate()).padStart(2, '0')}`; };
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const monthLabel = ymStr => MONTHS[+ymStr.slice(5, 7) - 1] + ' ' + ymStr.slice(0, 4);
function mulberry(seed) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }

// ---------- journal posting ----------
function linesFor(kind, amt, accountId, bankGl, e = {}) {
  // each line: [account, debit, credit, basis]; basis 'b' = both cash & accrual books, 'a' = accrual only, 'c' = cash only (Buildium-style cash basis)
  const UF = AC['1100'];
  switch (kind) {
    case 'charge': case 'latefee': return [[AR, amt, 0, 'a'], [accountId, 0, amt, 'a']];
    case 'credit': return [[accountId || AC['4000'], amt, 0, 'a'], [AR, 0, amt, 'a']];
    case 'payment': { const cash = (e._cash && e._cash.length ? e._cash : [[AC['4000'], amt]]).map(([a, v]) => [a, 0, v, 'c']); return [[bankGl || UF, amt, 0, 'b'], [AR, 0, amt, 'a'], ...cash]; }
    case 'refund': return [[AR, amt, 0, 'a'], [AC['2200'], amt, 0, 'c'], [bankGl, 0, amt, 'b']];
    case 'expense': return [[accountId, amt, 0, 'b'], [bankGl, 0, amt, 'b']];
    case 'mgmt_fee': return [[AC['6900'], amt, 0, 'b'], [bankGl, 0, amt, 'b']];
    case 'owner_draw': return [[AC['3200'], amt, 0, 'b'], [bankGl, 0, amt, 'b']];
    case 'contribution': return [[bankGl, amt, 0, 'b'], [accountId || AC['3100'], 0, amt, 'b']];
    case 'other_income': return [[bankGl || UF, amt, 0, 'b'], [accountId, 0, amt, 'b']];
    case 'opening': return [[bankGl, amt, 0, 'b'], [AC['3000'], 0, amt, 'b']];
    case 'deposit_in': return [[bankGl || UF, amt, 0, 'b'], [AC['2100'], 0, amt, 'b']];
    case 'deposit': return [[bankGl, amt, 0, 'b'], [UF, 0, amt, 'b']];
    case 'transfer': return [[accountId, amt, 0, 'b'], [bankGl, 0, amt, 'b']];
    case 'journal': case 'gl': return null; // manual multi-line entry: lines supplied by caller
    default: throw new HttpError('unknown entry kind ' + kind);
  }
}
const BANKGL = { 1: AC['1010'], 2: AC['1020'] }; // rebuilt from bank_accounts on every request (loadAccounts)
function journalRow(e) {
  const bankGl = e.bank_account_id ? (e._bankGl || BANKGL[e.bank_account_id] || AC['1010']) : null;
  let bank_amount = null;
  if (BANK_IN.has(e.kind) && e.bank_account_id) bank_amount = e.amount;
  if (BANK_OUT.has(e.kind) && e.bank_account_id) bank_amount = -e.amount;
  if (e.kind === 'deposit_in' && e.bank_account_id) bank_amount = e.amount;
  if (e.kind === 'deposit' && e.bank_account_id) bank_amount = e.amount;
  if (e.kind === 'transfer' && e.bank_account_id) bank_amount = -e.amount;
  if (e.kind === 'journal' || e.kind === 'gl') bank_amount = e.bank_amount ?? null;
  return { ...e, bank_amount, lines: (e.kind === 'journal' || e.kind === 'gl' || (e._custom && e.lines)) ? e.lines : linesFor(e.kind, e.amount, e.account_id, bankGl, e) };
}
const JCOLS = ['id','date','kind','memo','amount','account_id','property_id','unit_id','lease_id','tenant_id','vendor_id','owner_id','bank_account_id','bank_amount','ref','method','reconciled','void','created','company_id','src','jtype','payee','deposit_id'];
function journalStmts(d, e) {
  const r = journalRow(e);
  const out = [d.stmt(`INSERT INTO journal(${JCOLS.join(',')}) VALUES(${JCOLS.map(() => '?').join(',')})`, ...JCOLS.map(c => c === 'reconciled' || c === 'void' ? (r[c] || 0) : c === 'created' ? (r.created || nowISO()) : r[c]))];
  // a line may carry its own basis / property / company: [acct, dr, cr, basis, property_id, company_id]
  for (const [acct, dr, cr, basis, pid, cid, lm] of r.lines) if (dr || cr) out.push(lm ? d.stmt(`INSERT INTO jlines(journal_id,account_id,property_id,debit,credit,date,basis,company_id,unit_id,memo) VALUES(?,?,?,?,?,?,?,?,?,?)`, r.id, acct, pid !== undefined ? pid : r.property_id, dr, cr, r.date, basis || 'b', cid !== undefined ? cid : (r.company_id || null), r.unit_id || null, String(lm).slice(0, 200)) : d.stmt(`INSERT INTO jlines(journal_id,account_id,property_id,debit,credit,date,basis,company_id,unit_id) VALUES(?,?,?,?,?,?,?,?,?)`, r.id, acct, pid !== undefined ? pid : r.property_id, dr, cr, r.date, basis || 'b', cid !== undefined ? cid : (r.company_id || null), r.unit_id || null));
  return out;
}
// Buildium-style cash basis: a tenant payment is income in the accounts of the charges it pays (oldest first); anything beyond open charges is a prepayment
async function cashAllocation(d, leaseId, tenantId, amt) {
  const where = leaseId ? 'j.lease_id=?' : 'j.tenant_id=?';
  const rows = await d.all(`SELECT j.id, j.kind, j.amount, j.date, jl.account_id, jl.credit, jl.debit FROM journal j JOIN jlines jl ON jl.journal_id=j.id WHERE j.void=0 AND ${where} AND j.kind IN ('charge','latefee','credit','payment','refund') AND jl.basis IN ('a','b') AND jl.account_id<>? ORDER BY j.date, j.id`, leaseId || tenantId, AR);
  const buckets = []; let pool = 0;
  const seen = new Set();
  for (const r of rows) {
    if (r.kind === 'charge' || r.kind === 'latefee') { if (r.credit) buckets.push({ acct: r.account_id, left: r.credit }); }
    else if (!seen.has(r.id)) { seen.add(r.id); if (r.kind === 'refund') buckets.push({ acct: AC['2200'], left: r.amount }); else pool += r.amount; }
  }
  for (const b of buckets) { const x = Math.min(b.left, pool); b.left -= x; pool -= x; }
  const out = {}; let left = amt;
  for (const b of buckets) { if (!left) break; if (!b.left) continue; const x = Math.min(b.left, left); out[b.acct] = (out[b.acct] || 0) + x; left -= x; }
  if (left > 0) out[AC['2200']] = (out[AC['2200']] || 0) + left;
  return Object.entries(out).map(([a, v]) => [+a, v]);
}
async function post(d, e) {
  need(e.amount > 0, 'Amount must be more than zero');
  need(/^\d{4}-\d\d-\d\d$/.test(e.date || ''), 'Date is required');
  if (e.kind === 'payment' && !e._cash && (e.lease_id || e.tenant_id)) e._cash = await cashAllocation(d, e.lease_id, e.tenant_id, e.amount);
  if (e.lease_id && !e.tenant_id) { const l = await d.one('SELECT tenant_id FROM leases WHERE id=?', e.lease_id); if (l) e.tenant_id = l.tenant_id; }
  const mx = await d.one('SELECT COALESCE(MAX(id),0)+1 AS n FROM journal');
  e.id = mx.n;
  await d.batch(journalStmts(d, e));
  return e.id;
}

