  if (res.bill_id) { const b = await d.one('SELECT * FROM bills WHERE id=?', res.bill_id); if (b?.journal_id) await voidJournal(d, b.journal_id); await d.run(`UPDATE bills SET status='void' WHERE id=?`, res.bill_id); }
  if (res.recurring_id) { await d.run('UPDATE recurring_bills SET active=0 WHERE id=?', res.recurring_id); await d.run(`UPDATE bills SET status='void' WHERE recurring_id=? AND status='open'`, res.recurring_id); }
