    if (/\b(this year|ytd|so far this year)\b/.test(l)) { from = Y + '-01-01'; per = 'in ' + Y; }
    else if (/\blast year\b/.test(l)) { from = (Y - 1) + '-01-01'; to = (Y - 1) + '-12-31'; per = 'in ' + (Y - 1); }
