      const byP = {}; for (const r of rows) byP[r.property || 'Company level'] = (byP[r.property || 'Company level'] || 0) + sg * r.v;
      const ps = Object.entries(byP).filter(([, v]) => v).sort((x, y) => y[1] - x[1]);
      if (!dr.property_id && ps.length > 1) out += '\n' + ps.slice(0, 8).map(([k, v]) => `• ${k}: ${usd(v)}`).join('\n');
