// ---------- closing statement import ----------
const CLOSE_CAT_ACCT = { capitalize: '1500', loan_cost: '1510', prepaid: '1300', escrow: '1310', tax_proration: '6400', other: '1500' };

// ---------- HUD / closing statement → one journal entry, every line to his own accounts, tied to cash to/from close ----------
function closingDefaultAcct(label, category, kind, amount) {
  const L = String(label || '').toLowerCase(); const N = n => Object.values(ACBYID).find(a => a.name.toLowerCase() === n.toLowerCase())?.id;
  // purchase: buyer-side credits (tax prorations, seller credits, refunds) lower the property's capitalized closing cost, never the P&L
  if (kind !== 'refi' && amount != null && +amount < 0 && !/earnest|deposit|loan|payoff|pay off|mortgage|escrow|reserve/.test(L)) return N('Closing Cost') || N('Loan Closing Cost');
  const loanish = /lender|origination|discount|points|underwrit|appraisal|credit report|flood|tax service|mortgage broker|broker fee|application|lock|doc(ument)? prep|loan/.test(L);
  if (/payoff|pay off|existing loan|prior (loan|lien)/.test(L)) return N('Mortgage') || AC['2500'];
  if (category === 'tax_proration') return N('Taxes');
  if (/escrow|reserve|impound|initial deposit/.test(L) && !/escrow fee|settlement|closing fee/.test(L) || category === 'escrow') return N('Escrow Tax / Insurance') || N('Taxes');
  if (/interest/.test(L)) return N('Mortgage Interest');
  if (/insurance|hazard|homeowner/.test(L) && !/title/.test(L)) return N('Insurance');
  if (/purchase price|contract (sales )?price|sales? price/.test(L)) return N('Property Cost') || AC['1500'];
  if (category === 'capitalize') return kind === 'refi' ? (N('Loan Closing Cost') || N('Closing Cost')) : (N('Closing Cost') || N('Loan Closing Cost'));
  if (category === 'loan_cost') return N('Loan Closing Cost') || N('Closing Cost');
  if (/\btax(es)?\b|county|city|school|sewer|water/.test(L) && !/transfer|recording|record|fee\b|auditor|deed|stamp|certificate|cert\b|search/.test(L)) return N('Taxes');
  if (kind === 'refi' || loanish || /processing/.test(L) && !/title/.test(L)) return N('Loan Closing Cost') || N('Closing Cost');
  return N('Closing Cost') || N('Loan Closing Cost');
}
