  if (extra.length) x = { ...x, items: [...x.items, ...extra.map(e => ({ label: e.label, amount: e.amount, credit: true, account_id: e.account_id }))], cash_expected: x.cash_expected !== undefined && x.cash_expected !== '' && x.cash_expected !== null ? String((cents(x.cash_expected) - extra.reduce((s, e) => s + e.amount, 0)) / 100) : x.cash_expected };
  const r = await closingPost(d, user, x);
  if (extra.length) { r.funding = extra.map(e => ({ label: e.label, amount: e.amount }));
    try { const acq = await d.one('SELECT id, data FROM acquisitions WHERE journal_id=?', r.journal_id); if (acq) { const dd = JSON.parse(acq.data || '{}'); dd._funding = extra.map(e => ({ kind: e._fund.kind, name: e._fund.name || null, amount: e.amount, due: e._fund.due || null, rate: e._fund.rate || null })); await d.run('UPDATE acquisitions SET data=? WHERE id=?', JSON.stringify(dd), acq.id); } } catch (e) { } }
  return r;
