    leases: units.length ? await q(`SELECT COUNT(*) n FROM leases WHERE unit_id IN ${uIn}`, ...units.slice(0, 90)) : 0,
    bills: await q('SELECT COUNT(*) n FROM bills WHERE property_id=?', pid),
    loans: await q('SELECT COUNT(*) n FROM loans WHERE property_id=?', pid) + await q('SELECT COUNT(*) n FROM loan_properties WHERE property_id=?', pid),
    documents: await q('SELECT COUNT(*) n FROM files WHERE property_id=?', pid),
