      if (mode === '' && /^\s*Cash to Close\b/i.test(line) && amts.length) p1cash = amts[0].cents;
      if (mode === '' && /^\s*Sale Price\b/i.test(line) && amts.length && res.purchase_price == null) { res.purchase_price = amts[0].cents; res.confidence.purchase_price = 'low'; }
      if (mode === '' && /^\s*Loan Amount\b/i.test(line) && amts.length && res.loan_amount == null) { res.loan_amount = amts[0].cents; res.confidence.loan_amount = 'low'; }
