      if (!im) continue;
      toks = CL_tokens(line); amts = toks.filter(function (t) { return t.kind === 'amt'; });
      if (!amts.length) continue;
      var bat = 0, bbf = 0;
      if (spans && layout) {
        amts.forEach(function (a) { var c = CL_assign(a, spans, 6); if (c === 'bat') bat += a.cents; else if (c === 'bbf') bbf += a.cents; });
      } else {
        bat = amts[0].cents;
      }
      if (!bat && !bbf) continue;
      var label = CL_clean(CL_stripTokens(line, toks).replace(/^\s*\d{2}\s+/, '')).replace(/\(\s*\)/g, '').replace(/\s+per month for\s+\d+\s*mo\.?/i, '').replace(/\(\s*per day from.*?\)/i, '').replace(/\s{2,}/g, ' ');
      label = CL_clean(label.replace(/Deed:\s*Mortgage:\s*/i, ''));
      var cat;
      if (sect === 'A' || sect === 'B') cat = 'loan_cost';
      else if (sect === 'C') { cat = CL_categorize(label, ''); if (cat === 'other' || cat === 'prepaid') cat = 'loan_cost'; }
      else if (sect === 'E') cat = 'capitalize';
      else if (sect === 'F') { cat = CL_categorize(label, 'prepaids'); if (cat !== 'loan_cost') cat = 'prepaid'; }
      else if (sect === 'G') cat = 'escrow';
      else cat = CL_categorize(label, '');
      if (cat === 'tax_proration') cat = 'other';
      var sectName = { A: 'Origination Charges', B: 'Services Borrower Did Not Shop For', C: 'Services Borrower Did Shop For', E: 'Taxes and Other Government Fees', F: 'Prepaids', G: 'Initial Escrow Payment at Closing', H: 'Other' }[sect];
      if (bat) CL_pushItem(res, label, bat, cat, { section: sectName });
