      if (/^L\.\s/.test(lt)) { sub = 'L'; if (amts.length) totalL = amts[0].cents; continue; }
      if (/Total Due from Borrower/i.test(lt)) { if (amts.length) totalK = Math.abs(amts[0].cents); continue; }
      if (/Total Paid Already/i.test(lt)) { if (amts.length) totalL = Math.abs(amts[0].cents); continue; }
      if (/^Cash to Close/i.test(lt)) { if (amts.length) cashLine = { cents: amts[0].cents, toBorrower: /\bto borrower\b/i.test(lt) && !/from/i.test(lt) }; continue; }
      if (/^Adjustments for Items Paid by Seller/i.test(lt)) { sub = 'K'; continue; }
      if (/^Adjustments for Items Unpaid by Seller/i.test(lt)) { sub = 'L'; continue; }
      var it = /^(\d{2})\s+(.*)$/.exec(lt);
