  const txns = await d.all(`SELECT * FROM bank_txns WHERE status='unmatched' ORDER BY date, id`);
  const linked = new Set((await d.all(`SELECT bank_account_id, journal_id FROM bank_txns WHERE journal_id IS NOT NULL AND status='matched'`)).map(r => r.bank_account_id + '|' + r.journal_id));
  const gls = banks.map(b => b.account_id);
  const booked = await d.all(`SELECT jl.journal_id jid, jl.account_id, SUM(jl.debit - jl.credit) v, MIN(jl.date) date, j.payee, j.memo, j.jtype, j.property_id, j.company_id, v.name vname, t.first, t.last FROM jlines jl JOIN journal j ON j.id=jl.journal_id LEFT JOIN vendors v ON v.id=j.vendor_id LEFT JOIN tenants t ON t.id=j.tenant_id WHERE j.void=0 AND jl.basis IN ('b','c') AND jl.account_id IN (${gls.map(() => '?').join(',')}) GROUP BY jl.journal_id, jl.account_id`, ...gls);
  const cand = {}; for (const r of booked) { const b = bankByGl[r.account_id]; if (!b || !r.v || linked.has(b.id + '|' + r.jid)) continue; (cand[b.id] || (cand[b.id] = [])).push(r); }
  const words = r => [r.payee, r.vname, r.first, r.last].filter(Boolean).join(' ').toUpperCase().split(/[^A-Z]+/).filter(w => w.length > 3);
