    if (bill && t.amount < 0) { sug(t, { type: 'bill', confidence: (bill.amount - (bill.amount_paid || 0) === amt || bill.ref) ? 'high' : 'medium', bill_id: bill.id, property_id: bill.property_id, label: `Payment on ${bill.vname} bill ${bill.ref || ''} (${money0(bill.amount)}, ${money0(bill.amount - (bill.amount_paid || 0))} open)` }); continue; }
