  if (ty === 'bill') return e.bill_id ? '' : 'Pick the open bill';
  if (ty === 'loan') return e.loan_id ? '' : 'Pick the loan';
  if (ty === 'transfer') return e.pair_txn_id ? '' : 'Pick the other side of the transfer';
