// ---------- v21: mortgages — statement upload/reader, payment history, blanket loans, repeating payments ----------
SCHEMA.push(`CREATE TABLE IF NOT EXISTS loan_properties(id INTEGER PRIMARY KEY, loan_id INTEGER, property_id INTEGER, pct REAL, fixed INTEGER, released_on TEXT, release_amount INTEGER, created TEXT)`);
SCHEMA.push(`CREATE TABLE IF NOT EXISTS loan_history(id INTEGER PRIMARY KEY, loan_id INTEGER, at TEXT, user_email TEXT, kind TEXT, before TEXT, after TEXT, file_id INTEGER, note TEXT)`);
const loanReady = new Set();
async function ensureLoanX(d) { const co = MCTX.co || 1; if (loanReady.has(co)) return; await d.run(`CREATE TABLE IF NOT EXISTS loan_properties(id INTEGER PRIMARY KEY, loan_id INTEGER, property_id INTEGER, pct REAL, fixed INTEGER, released_on TEXT, release_amount INTEGER, created TEXT)`); await d.run(`CREATE TABLE IF NOT EXISTS loan_history(id INTEGER PRIMARY KEY, loan_id INTEGER, at TEXT, user_email TEXT, kind TEXT, before TEXT, after TEXT, file_id INTEGER, note TEXT)`); loanReady.add(co); }
// the properties a loan covers, with each property's share (single-property loans: that property at 100%)
async function loanAlloc(d, L) {
  await ensureLoanX(d);
  const rows = await d.all('SELECT lp.*, p.name property FROM loan_properties lp LEFT JOIN properties p ON p.id=lp.property_id WHERE lp.loan_id=? ORDER BY lp.id', L.id);
  const act = rows.filter(r => !r.released_on);
  if (!act.length) return { blanket: false, houses: L.property_id ? [{ property_id: L.property_id, property: L.property || null, pct: 100, share: 1 }] : [], released: rows.filter(r => r.released_on) };
  const tot = act.reduce((s, r) => s + (+r.pct || 0), 0) || 100;
  return { blanket: act.length > 1, houses: act.map(r => ({ property_id: r.property_id, property: r.property, pct: +r.pct || 0, share: (+r.pct || 0) / tot })), released: rows.filter(r => r.released_on).map(r => ({ property_id: r.property_id, property: r.property, released_on: r.released_on, release_amount: r.release_amount })) };
}
// split cents across properties by share; the last property takes the rounding
function splitCents(amount, houses) { let left = amount; return houses.map((h, i) => { const v = i === houses.length - 1 ? left : Math.round(amount * h.share); left -= v; return [h.property_id, v]; }); }
async function loanPaymentLines(d, L, sp, amt, bankGl) {
  const esc = ACCTS.find(a => /^escrow\s+tax/i.test(a[2]))?.[0] || AC['1310'];
  const al = await loanAlloc(d, L); const hs = al.houses.length ? al.houses : [{ property_id: L.property_id, share: 1 }];
  const lines = [];
  for (const [acct, v] of [[AC['2500'], sp.principal], [AC['6960'], sp.interest], [esc, sp.escrow]]) if (v) for (const [pid, part] of splitCents(v, hs)) if (part) lines.push([acct, part, 0, 'b', pid]);
  lines.push([bankGl, 0, amt, 'b', hs.length === 1 ? hs[0].property_id : null]);
  return lines;
}

// v23: blanket loans — the repeating payment and edited payments split across the loan's properties too
async function loanBillLines23(d, r, nd) {
  const L = await d.one('SELECT * FROM loans WHERE recurring_id=?', r.id); if (!L) return null;
  const al = await loanAlloc(d, L); const hs = al.houses.length ? al.houses : [{ property_id: r.property_id || L.property_id, share: 1 }];
  const AP = AC['2000']; const sp = L.pi > 0 ? loanSplit(L, nd, r.amount) : { unknown: true };
  let lines;
  if (!sp.unknown) lines = (await loanPaymentLines(d, L, sp, r.amount, AP)).map(l => [l[0], l[1], l[2], 'a', l[4] ?? null]);
  else { lines = splitCents(r.amount, hs).filter(([, v]) => v).map(([pid, v]) => [r.account_id, v, 0, 'a', pid]); lines.push([AP, 0, r.amount, 'a', hs.length === 1 ? hs[0].property_id : null]); }
  if (hs.length === 1 && lines.every(l => l[0] === r.account_id || l[0] === AP)) return null; // a plain one-house bill: the usual entry
  return { L, lines, sp };
}
function blanketLines23(nl, hs, accts) {
  if (!hs || hs.length < 2) return nl;
  const isLoan = l => accts.includes(l.account_id) && l.debit > 0;
  // an entry already split across properties keeps its own split (a property released later stays in the months before its release)
  const byP = {}; for (const l of nl) if (isLoan(l) && l.property_id) byP[l.property_id] = (byP[l.property_id] || 0) + l.debit;
  const ks = Object.keys(byP); const totP = ks.reduce((s, k) => s + byP[k], 0);
  if (ks.length > 1 && totP > 0) hs = ks.map(k => ({ property_id: +k, share: byP[k] / totP }));
  const out = [];
  for (const a of accts) for (const bs of [...new Set(nl.filter(l => l.account_id === a && l.debit > 0).map(l => l.basis || ''))]) { const ls = nl.filter(l => l.account_id === a && l.debit > 0 && (l.basis || '') === bs); const tot = ls.reduce((s, l) => s + l.debit, 0); if (!tot) continue; for (const [pid, v] of splitCents(tot, hs)) if (v) out.push({ ...ls[0], property_id: pid, debit: v, credit: 0 }); }
  return [...out, ...nl.filter(l => !isLoan(l))];
}

