  let addr = null, addrI = -1; for (let i = 0; i < flat.length; i++) { const m = flat[i].match(/property\s*(?:address)?\s*:\s*(.*)$/i) || flat[i].match(/^property address\s*(.*)$/i); if (m) { addrI = i; addr = (m[1] || '').trim(); if (!/\d/.test(addr) && flat[i + 1]) { addr = flat[i + 1]; addrI = i + 1; } if (addr && !/,|\b[A-Z]{2}\b\s*\d{5}/.test(addr) && flat[i + 2] && /\b[A-Z]{2}\s+\d{5}/.test(flat[i + 2]) && !/\d{5}/.test(addr)) addr += ', ' + flat[i + 2]; break; } }
