  const pickCell = (re, not) => { for (const c of vcells) if (c.vals.length === 1 && re.test(c.label) && !(not && not.test(c.label))) return msCents(c.vals[0]); return null; };
  const princ2 = pickCell(/^(?:principal|principal\s*(?:payment|due|amount))\s*:?$/i), intr2 = pickCell(/^(?:interest|interest\s*(?:payment|due|amount))\s*:?$/i), esc2 = pickCell(/^escrow\b(?!.*balance)/i, /balance|year|ytd|paid|disburse|shortage|surplus|advance/i);
