  const acc = await d.all(`SELECT jl.account_id a, SUM(jl.debit - jl.credit) v, SUM(CASE WHEN jl.date>=? THEN jl.debit - jl.credit ELSE 0 END) y FROM jlines jl JOIN journal j ON j.id=jl.journal_id WHERE j.void=0 AND jl.company_id=? AND jl.basis IN ('b','c') GROUP BY jl.account_id`, Y + '-01-01', id);
  const expenses = acc.filter(r => ACBYID[r.a]?.type === 'expense').map(r => ({ account_id: r.a, account: ACBYID[r.a].name, all: r.v, year: r.y })).sort((x, y) => y.all - x.all);
  const entries = await d.all(`SELECT j.id, j.date, j.memo, j.amount, j.jtype, j.kind, j.payee, v.name vendor, (SELECT a.name FROM jlines jl JOIN gl_accounts a ON a.id=jl.account_id WHERE jl.journal_id=j.id AND jl.company_id=? AND a.type='expense' LIMIT 1) account FROM journal j LEFT JOIN vendors v ON v.id=j.vendor_id WHERE j.void=0 AND (j.company_id=? OR j.id IN (SELECT journal_id FROM jlines WHERE company_id=?)) ORDER BY j.date DESC, j.id DESC LIMIT 150`, id, id, id);
