// GL account register: every posting to one account, filterable by property / company / dates / basis, with totals by property
async function accountRegister(d, id, url) {
  const acct = ACBYID[id]; need(acct, 'Account not found', 404);
  const q = k => url.searchParams.get(k);
  const basis = BASIS(q('basis') || 'cash'), from = q('from') || '0000-01-01', to = q('to') || '9999-12-31';
  const w = ['j.void=0', "jl.basis IN ('b',?)", 'jl.account_id=?', 'jl.date>=?', 'jl.date<=?']; const a = [basis, id, from, to];
  if (q('property_id')) { w.push('jl.property_id=?'); a.push(+q('property_id')); }
  if (q('company_id')) { w.push('jl.company_id=?'); a.push(+q('company_id')); }
  if (q('q')) { w.push("(j.memo LIKE ? OR j.payee LIKE ? OR v.name LIKE ?)"); const s = '%' + q('q') + '%'; a.push(s, s, s); }
  const lines = await d.all(`SELECT jl.id lid, jl.date, jl.debit, jl.credit, jl.property_id, jl.company_id, j.memo, jl.memo lmemo, jl.unit_id, un.name unit, j.kind, j.jtype, j.payee, j.id jid, j.ref, j.method, p.name property, c.name company, t.first, t.last, v.name vendor FROM jlines jl JOIN journal j ON j.id=jl.journal_id LEFT JOIN properties p ON p.id=jl.property_id LEFT JOIN units un ON un.id=jl.unit_id LEFT JOIN companies c ON c.id=jl.company_id LEFT JOIN tenants t ON t.id=j.tenant_id LEFT JOIN vendors v ON v.id=j.vendor_id WHERE ${w.join(' AND ')} ORDER BY jl.date, jl.id`, ...a);
  const nat = DEBIT_NORMAL(acct.type) ? 1 : -1;
  let run = 0; const byProp = {};
  for (const l of lines) { const v = (l.debit - l.credit) * nat; run += v; l.amount = v; l.balance = run; const k = l.property || l.company || 'Company level'; byProp[k] = (byProp[k] || 0) + v; }
  return { account: acct, basis: basis === 'a' ? 'accrual' : 'cash', from: q('from') || null, to: q('to') || null, total: run, count: lines.length, by_property: Object.entries(byProp).map(([name, amount]) => ({ name, amount })).sort((x, y) => Math.abs(y.amount) - Math.abs(x.amount)), lines: lines.reverse().slice(0, +(q('limit') || 1000)) };
}

// "Repeats monthly" chip: which recurring item made this entry (a repeating bill, or a mortgage payment)
async function recTagger(d, pids) {
  const loans = await d.all(`SELECT id, property_id, vendor_id, lender, recurring_id FROM loans`);
  let lp = []; try { lp = await d.all('SELECT loan_id, property_id FROM loan_properties WHERE released_on IS NULL'); } catch (e) { }
  const billRec = new Map((await d.all(`SELECT journal_id, recurring_id FROM bills WHERE recurring_id IS NOT NULL AND journal_id IS NOT NULL`)).map(r => [r.journal_id, r.recurring_id]));
  return (j, pid) => { const rid = billRec.get(j.id); if (rid) { const L = loans.find(L => L.recurring_id === rid); return L ? { kind: 'mortgage', id: L.id, label: 'Repeats monthly', href: `#/loan/${L.id}` } : { kind: 'bill', id: rid, label: 'Repeats monthly', href: `#/repeating?t=bill&open=${rid}` }; }
    const p = pid ?? j.property_id; const nm = String(j.vendor || j.payee || '').toLowerCase(); const onHouse = L => L.property_id === p || lp.some(x => x.loan_id === L.id && x.property_id === p);
    const L = loans.find(L => onHouse(L) && ((L.vendor_id && L.vendor_id === j.vendor_id) || (nm && String(L.lender || '').toLowerCase().split(/[ (]/)[0].length > 2 && nm.includes(String(L.lender || '').toLowerCase().split(/[ (]/)[0]))));
    if (L && (/mortgage|interest|escrow/i.test(j.accts || '') || /check|mortgage/i.test(j.jtype || ''))) return { kind: 'mortgage', id: L.id, label: 'Repeats monthly', href: `#/loan/${L.id}` };
    return null; };
}
async function journalDetail(d, id) {
  const j = await d.one(`SELECT j.*, p.name property, c.name company, t.first, t.last, v.name vendor, u.name unit FROM journal j LEFT JOIN properties p ON p.id=j.property_id LEFT JOIN companies c ON c.id=j.company_id LEFT JOIN tenants t ON t.id=j.tenant_id LEFT JOIN vendors v ON v.id=j.vendor_id LEFT JOIN units u ON u.id=j.unit_id WHERE j.id=?`, id);
  need(j, 'Entry not found', 404);
  j.lines = (await d.all(`SELECT jl.*, p.name property, c.name company FROM jlines jl LEFT JOIN properties p ON p.id=jl.property_id LEFT JOIN companies c ON c.id=jl.company_id WHERE jl.journal_id=? ORDER BY jl.id`, id)).map(l => ({ ...l, account: ACBYID[l.account_id]?.name, code: ACBYID[l.account_id]?.code }));
  try { j.recurring = (await recTagger(d))({ ...j, accts: j.lines.map(l => l.account).join(',') }); } catch (e) { j.recurring = null; }
  return j;
}
// global search: tenants, vendors, properties, companies, accounts, and transactions by memo / payee / amount
async function globalSearch(d, q) {
  q = String(q || '').trim(); if (!q) return { q, results: [] };
  const s = '%' + q + '%'; const out = [];
  for (const t of await d.all(`SELECT id, first, last, status FROM tenants WHERE (first || ' ' || last) LIKE ? OR email LIKE ? OR phone LIKE ? LIMIT 20`, s, s, s)) out.push({ type: 'tenant', id: t.id, title: `${t.first} ${t.last}`, sub: t.status || 'Tenant', href: `tenant/${t.id}` });
  for (const p of await d.all(`SELECT id, name, city FROM properties WHERE name LIKE ? OR address LIKE ? LIMIT 20`, s, s)) out.push({ type: 'property', id: p.id, title: p.name, sub: p.city || 'Property', href: `property/${p.id}` });
  for (const c of await d.all(`SELECT id, name FROM companies WHERE name LIKE ? LIMIT 10`, s)) out.push({ type: 'company', id: c.id, title: c.name, sub: 'Company / entity', href: `company/${c.id}` });
  for (const v of await d.all(`SELECT id, name, trade FROM vendors WHERE name LIKE ? LIMIT 20`, s)) out.push({ type: 'vendor', id: v.id, title: v.name, sub: v.trade || 'Vendor', href: `vendor/${v.id}` });
  for (const a of ACCTS.filter(a => (a[2] + ' ' + a[1]).toLowerCase().includes(q.toLowerCase())).slice(0, 15)) out.push({ type: 'account', id: a[0], title: `${a[1]} ${a[2]}`, sub: cap1(a[3]) + ' account', href: `account/${a[0]}` });
  for (const [re, title, sub, href] of [[/recur|repeat|monthly|autopay|subscri/i, 'Recurring payments', 'Mortgages, bills, rent charges', 'repeating'], [/mortg|morg|loan|escrow/i, 'Mortgages', 'Balances & every payment', 'loans'], [/mortg|morg|loan/i, 'Mortgage payments report', 'All loans by month', 'mortreport']]) if (re.test(q) && !out.some(o => o.href === href)) out.unshift({ type: 'page', id: href, title, sub, href });
  const amt = cents(q); const amtOk = /^[$\d.,\s-]+$/.test(q) && Number.isFinite(amt) && amt !== 0;
  const tx = await d.all(`SELECT j.id, j.date, j.kind, j.jtype, j.memo, j.amount, j.payee, p.name property, c.name company, v.name vendor, t.first, t.last FROM journal j LEFT JOIN properties p ON p.id=j.property_id LEFT JOIN companies c ON c.id=j.company_id LEFT JOIN vendors v ON v.id=j.vendor_id LEFT JOIN tenants t ON t.id=j.tenant_id WHERE j.void=0 AND (j.memo LIKE ? OR j.payee LIKE ? OR v.name LIKE ? OR j.ref LIKE ? ${amtOk ? 'OR j.amount=? OR j.id IN (SELECT journal_id FROM jlines WHERE debit=? OR credit=?)' : ''}) ORDER BY j.date DESC LIMIT 60`, s, s, s, s, ...(amtOk ? [Math.abs(amt), Math.abs(amt), Math.abs(amt)] : []));
  for (const j of tx) out.push({ type: 'entry', id: j.id, title: `${j.payee || j.vendor || (j.first ? j.first + ' ' + j.last : '') || j.memo || cap1(j.kind)}`, sub: `${j.date} · ${j.jtype || cap1(j.kind)} · ${j.property || j.company || 'Company level'}${j.memo && j.memo !== j.payee ? ' · ' + j.memo : ''}`, amount: j.amount, href: `entry/${j.id}` });
  return { q, results: out };
}

