  need((await hashPw(String(x.current || ''), u.salt)) === u.pass, 'Current password is not right', 403);
  need(String(x.next || '').length >= 8, 'New password needs 8+ characters');
  const salt = randHex(16); await d.run('UPDATE users SET pass=?, salt=? WHERE id=?', await hashPw(x.next, salt), salt, u.id);
  if (user._token) try { await d.run('DELETE FROM sessions WHERE user_id=? AND token<>?', u.id, user._token); } catch (e) { }
