    const r = await d.run('INSERT INTO payments(processor,status,amount,tenant_id,lease_id,method,ref,journal_id,created,meta) VALUES(?,?,?,?,?,?,?,?,?,?)', pid, res.status, amount, l.tenant_id, l.id, x.method || 'card', res.ref, jid, nowISO(), JSON.stringify({ last4: String(x.last4 || '').slice(-4) }));
    return J({ id: r.last_row_id, status: res.status, ref: res.ref, demo: pid === 'demo', client_secret: res.client_secret || null });
