    await d.run('INSERT INTO selfhelp_log(created,property_id,unit_id,tenant_id,problem,outcome,wo_id,name,phone,lang) VALUES(?,?,?,?,?,?,?,?,?,?)', nowISO(), det?.property_id || null, det?.unit_id || null, user.tenant_id, PROBLEMS[x.problem] ? x.problem : 'other', 'fixed', null, user.name, null, x.lang === 'es' ? 'es' : 'en');
