    if (req.method === 'POST') { const x = await body(req); if (String(x.note || '').trim()) await d.run('INSERT INTO wo_events(wo_id,author,kind,body,created) VALUES(?,?,?,?,?)', w.id, user.name, 'note', String(x.note).trim().slice(0, 4000), nowISO()); for (const f of (x.photo_ids || [])) await d.run('UPDATE files SET wo_id=? WHERE id=? AND wo_id IS NULL AND uploaded_by=?', w.id, f, user.id); }
