    if (qp('q')) { const q = '%' + qp('q').trim().toLowerCase() + '%'; w.push(`(LOWER(COALESCE(f.name,'')||' '||COALESCE(f.title,'')||' '||COALESCE(f.note,'')||' '||COALESCE(f.category,'')||' '||COALESCE(p.name,'')||' '||COALESCE(v.name,'')||' '||COALESCE(t.first,'')||' '||COALESCE(t.last,'')) LIKE ?)`); a.push(q); }
    let rows = (await d.all(`${DOC_SEL} WHERE ${w.join(' AND ')} ORDER BY COALESCE(f.doc_date, substr(f.created,1,10)) DESC, f.id DESC LIMIT 1000`, ...a)).map(docRow11);
    if (qp('category')) rows = rows.filter(r => r.category === qp('category'));
    if (qp('q')) { const q = qp('q').trim().toLowerCase(); const lab = DOC_CATS.filter(c => c[1].toLowerCase().includes(q)).map(c => c[0]); if (lab.length) { const more = (await d.all(`${DOC_SEL} WHERE COALESCE(f.deleted,0)=0 AND f.wo_id IS NULL ORDER BY f.id DESC LIMIT 1000`)).map(docRow11).filter(r => lab.includes(r.category) && !rows.some(x => x.id === r.id)); rows = rows.concat(more); } }
