      await post(d, { date: T, kind: 'credit', memo: `Late fee waived (${fd(e.date)})`, amount: e.amount, account_id: e.account_id, lease_id: e.lease_id, tenant_id: e.tenant_id, property_id: e.property_id, unit_id: e.unit_id, ref: 'WAIVE-' + e.id, src: 'app:waive' });
