    return J({ groups: GROUPS.map(([key, label]) => ({ key, label, properties: props.filter(p => grpOf(p) === key).map(p => ({ ...p, default: !p.grp })), banks: banks.filter(x => x.kind !== 'other' && grpOf(x) === key).map(x => ({ ...x, default: !x.grp })) })), dues: await groupDues(d) });
