  for (const l of todo) {
    let label = null;
    if (l.group !== 'paid') { const hit = src.find(it => !it.used && it.amount === l.amount && !fundItem(it)); if (hit) { hit.used = true; label = hit.label; } }
    if (!label) label = l.label; // plain name for price / cash / deposit / loans
    if (label) set.push([l.id, label.slice(0, 200)]);
  }
  need(set.length, 'No line names found on the statement');
