  await ensureAudit(d); await d.run('INSERT INTO entry_audit(journal_id,at,user_id,user_email,action,before,after,note) VALUES(?,?,?,?,?,?,?,?)', dl.journal_id, nowISO(), user.id, user.email, 'edit', JSON.stringify(before), JSON.stringify(await entrySnapshot(d, dl.journal_id)), 'Line names added from the HUD (amounts unchanged)');
  MCTX.wrote = (MCTX.wrote || 0) + 1;
  const after = await deal26(d, pid);
