  const pid = +x.property_id || null; const o = +x.owner_id ? await d.one('SELECT * FROM owners WHERE id=?', +x.owner_id) : null;
  const who = o ? o.name : String(x.name || '').trim(); need(who, 'Pick who put the money in');
  const memo = String(x.memo || '').trim().slice(0, 200);
