  if (pp) { const r = await recordPartnerTxn(d, pid, { owner_id: o.id, amount: amt, date, kind: 'contribution', source: 'personal', bank_account_id: ba.id, memo }); return { ok: true, journal_id: r.journal_id, kind: 'partner' }; }
