  const owedNow = ((await loansFromPeople25(d)).find(l => l.id === acc.id) || {}).balance || 0;
  const date = /^\d{4}-\d\d-\d\d$/.test(x.date || '') ? x.date : todayNY(); const who = acc.name.replace(/^Loan from /, '');
  const memo0 = String(x.memo || '').trim().slice(0, 200);
