  const st = []; for (const id of dt.voided || []) st.push(d.stmt('UPDATE journal SET void=0 WHERE id=?', id)); for (const id of dt.credits || []) st.push(d.stmt('UPDATE journal SET void=1 WHERE id=?', id));
