  if (b === 'moveout' && c && M === 'POST' && !op) return J(await moveOut26(d, user, +c, await body(req)));
  if (b === 'moveout' && c && M === 'POST' && op === 'undo') return J(await moveOutUndo26(d, user, +c));
  if (b === 'deposit' && c && M === 'GET') return J(await depositOf26(d, +c));
  if (b === 'deposit' && c && M === 'POST' && op === 'settle') return J(await depositSettle26(d, user, +c, await body(req)));
  if (b === 'deposit' && c && M === 'POST' && op === 'undo') return J(await depositUndo26(d, user, +c));
  if (b === 'applicants' && !c && M === 'GET') return J(await applicants26(d, { property_id: +qp('property_id') || null, unit_id: +qp('unit_id') || null }));
  if (b === 'applicants' && !c && M === 'POST') return J(await applicantAdd26(d, user, await body(req)));
  if (b === 'applicants' && c && M === 'POST' && op) return J(await applicantDecide26(d, user, +c, op, await body(req)));
  if (b === 'house' && c && M === 'GET') return J(await house26(d, +c));
  if (b === 'health' && M === 'GET') return J(await health26(d));
  if (b === 'dups' && !c && M === 'GET') return J(await dupGroups26(env, d, +url.searchParams.get('property_id') || null));
  if (b === 'dups' && c === 'keep' && M === 'POST') { const x = await body(req); return J(await dupKeep26(env, d, user, +x.keep_id, x.remove_ids)); }
  if (b === 'dups' && c === 'undo' && M === 'POST') { const x = await body(req); return J(await dupUndo26(d, user, +x.keep_id)); }
  if (b === 'vacant' && c && M === 'GET') { await ensureMo26(d); const us = await d.all(`SELECT u.id, u.name, u.vacant_since, u.market_rent, (SELECT rent FROM leases WHERE unit_id=u.id ORDER BY start DESC LIMIT 1) last_rent, (SELECT deposit FROM leases WHERE unit_id=u.id ORDER BY start DESC LIMIT 1) last_deposit, (SELECT COUNT(*) FROM applicants26 a WHERE a.unit_id=u.id AND a.status='new') applicants FROM units u WHERE u.property_id=? AND NOT EXISTS (SELECT 1 FROM leases l WHERE l.unit_id=u.id AND l.status='active') ORDER BY u.name`, +c); return J(us); }
  if (typeof x26eRoute === 'function') { const r = await x26eRoute(env, d, user, parts, M, req, url); if (r) return r; }
  return null;
