// ---------- v23c: + Add a loan (plain form; blanket = several properties with a split) ----------
async function loanAdd23(d, user, x) {
  await ensureLoanX(d);
  const lender = String(x.lender || '').trim().slice(0, 80); need(lender, 'Enter the lender');
  const bal = cents(x.balance || 0); need(bal > 0, 'Enter the current balance');
  const pi = cents(x.pi || 0); need(pi > 0, 'Enter the monthly principal & interest');
  const esc_ = cents(x.escrow || 0) || 0; const total = pi + esc_;
  const dueDay = Math.max(1, Math.min(28, +x.due_day || 1));
  const bid = +x.bank_account_id || null; if (bid) need(await d.one('SELECT id FROM bank_accounts WHERE id=?', bid), 'Bank account not found');
  let hs = (Array.isArray(x.houses) ? x.houses : []).map(h => ({ property_id: +h.property_id, pct: +h.pct || 0, fixed: cents(h.fixed || 0) || 0 })).filter(h => h.property_id);
  need(hs.length, 'Pick the property this loan is on');
  if (!x.new_loan_ok) for (const h of hs) { const sims = await similarLoans26(d, h.property_id, pi, bal); need(!sims.length, `DUPLOAN${sims.length ? '#' + sims[0].id : ''}: This property already has a mortgage like this (${sims.map(L => `${L.lender}${L.last4 ? ' ••' + L.last4 : ''}`).join(', ')}). Is it the same loan with a new servicer? Then update that one instead.`); }
  for (const h of hs) need(await d.one('SELECT id FROM properties WHERE id=?', h.property_id), 'Property not found');
  const method = ['equal', 'price', 'pct', 'fixed'].includes(x.split) ? x.split : 'equal';
  if (hs.length > 1) {
    if (method === 'equal') hs.forEach(h => { h.pct = +(100 / hs.length).toFixed(4); });
    else if (method === 'price') { const ps = await d.all(`SELECT id, purchase_price FROM properties WHERE id IN (${hs.map(() => '?').join(',')})`, ...hs.map(h => h.property_id)); const pp = id => ps.find(p => p.id === id)?.purchase_price || 0; const tot = hs.reduce((s, h) => s + pp(h.property_id), 0); need(tot > 0 && hs.every(h => pp(h.property_id) > 0), 'Some properties have no purchase price yet. Use Equal or Custom % instead.'); hs.forEach(h => { h.pct = +(pp(h.property_id) / tot * 100).toFixed(4); }); }
    else if (method === 'pct') { const t = hs.reduce((s, h) => s + h.pct, 0); need(Math.abs(t - 100) < 0.05, `The shares add up to ${+t.toFixed(2)}%, not 100%`); }
    else { const t = hs.reduce((s, h) => s + h.fixed, 0); need(t > 0, 'Enter the amount per property'); need(Math.abs(t - total) <= 1 || Math.abs(t - pi) <= 1, `The amounts add up to ${(t / 100).toFixed(2)}, the monthly payment is ${(total / 100).toFixed(2)}`); hs.forEach(h => { h.pct = +(h.fixed / t * 100).toFixed(4); }); }
  } else hs[0].pct = 100;
  const v = await d.one('SELECT id FROM vendors WHERE lower(name)=lower(?)', lender); const vid = v ? v.id : (await d.run('INSERT INTO vendors(name,trade,phone,email) VALUES(?,?,?,?)', lender, 'Lender', '', '')).last_row_id;
  const T = todayNY(); const first = /^\d{4}-\d\d-\d\d$/.test(x.first_payment || '') ? x.first_payment : null;
  const last4 = String(x.last4 || '').replace(/\D/g, '').slice(-4) || null;
  if (last4) { const dup = await d.one('SELECT id FROM loans WHERE last4=? AND lower(lender)=lower(?)', last4, lender); need(!dup, `${lender} ••${last4} is already on the Mortgages page`); }
  const lr = await d.run('INSERT INTO loans(property_id,lender,vendor_id,last4,balance,balance_date,rate,pi,escrow,total,due_day,status,notes,bank_account_id,orig_amount,orig_date,term_months,estimated,updated,created) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
    hs[0].property_id, lender, vid, last4, bal, T, +x.rate || null, pi, esc_ || null, total, dueDay, 'entered', String(x.notes || '').slice(0, 300) || null, bid, cents(x.orig_amount || 0) || null, first, +x.term_months || null, 0, nowISO(), nowISO());
  const lid = lr.last_row_id;
  if (hs.length > 1) for (const h of hs) await d.run('INSERT INTO loan_properties(loan_id,property_id,pct,fixed,created) VALUES(?,?,?,?,?)', lid, h.property_id, h.pct, h.fixed || null, nowISO());
  // the monthly payment: a repeating bill linked to the loan (posts split P/I/escrow across the houses)
  let next = first; if (!next || next < T) { const m0 = T.slice(0, 8) + String(dueDay).padStart(2, '0'); next = m0 >= T ? m0 : addMonths(T.slice(0, 7), 1) + '-' + String(dueDay).padStart(2, '0'); if (first && first > next) next = first; }
  let rid = null; if (x.repeat !== false && x.repeat !== '0') { rid = (await d.run('INSERT INTO recurring_bills(vendor_id,property_id,account_id,amount,memo,frequency,next_date,active,created,method) VALUES(?,?,?,?,?,?,?,?,?,?)', vid, hs[0].property_id, AC['2500'], total, `${lender}${last4 ? ' ••' + last4 : ''} mortgage payment`, 'monthly', next, 1, nowISO(), 'ACH')).last_row_id; await d.run('UPDATE loans SET recurring_id=? WHERE id=?', rid, lid); }
  try { await d.run('INSERT INTO loan_history(loan_id,at,user_email,kind,before,after,note) VALUES(?,?,?,?,?,?,?)', lid, nowISO(), user?.email || null, 'added', null, JSON.stringify(await d.one('SELECT * FROM loans WHERE id=?', lid)), `Added by hand${hs.length > 1 ? ` · covers ${hs.length} properties (${method})` : ''}`); } catch (e) { }
  return { ok: true, id: lid, recurring_id: rid, next_payment: rid ? next : null, houses: hs };
}

