// what is still open on a lease, per income/liability account (same rule as a normal payment: oldest first)
async function openByAcct23(d, leaseId) {
  const rows = await d.all(`SELECT j.id, j.kind, j.amount, jl.account_id, jl.credit FROM journal j JOIN jlines jl ON jl.journal_id=j.id WHERE j.void=0 AND j.lease_id=? AND j.kind IN ('charge','latefee','credit','payment','refund') AND jl.basis IN ('a','b') AND jl.account_id<>? ORDER BY j.date, j.id`, leaseId, AR);
  const buckets = []; let pool = 0; const seen = new Set();
  for (const r of rows) { if (r.kind === 'charge' || r.kind === 'latefee') { if (r.credit) buckets.push({ acct: r.account_id, left: r.credit }); } else if (!seen.has(r.id)) { seen.add(r.id); if (r.kind === 'refund') buckets.push({ acct: AC['2200'], left: r.amount }); else pool += r.amount; } }
  for (const b of buckets) { const x = Math.min(b.left, pool); b.left -= x; pool -= x; }
  const out = {}; for (const b of buckets) if (b.left > 0) out[b.acct] = (out[b.acct] || 0) + b.left; return out;
}
