  return { property: { id: p.id, name: p.name }, leases, manager: { ...ext, vendor: vend?.name || null }, accounts: { broker: await dedAcct23(d, 'broker'), mgmt: await dedAcct23(d, 'mgmt'), repair: await dedAcct23(d, 'repair') } };
