  if (x.net !== undefined && x.net !== '' && x.net !== null) { const n2 = cents(x.net); need(Math.abs(n2 - net) <= 1, `Doesn't add up: ${(gross / 100).toFixed(2)} paid − ${(dsum / 100).toFixed(2)} deductions = ${(net / 100).toFixed(2)}, not ${(n2 / 100).toFixed(2)}. Assign the ${(Math.abs(n2 - net) / 100).toFixed(2)} difference first.`); }
