  const mlab = /^\d{4}-\d\d$/.test(x.month || '') ? `${MONTHS[+x.month.slice(5, 7) - 1]} ${x.month.slice(0, 4)}` : `${MONTHS[+date.slice(5, 7) - 1]} ${date.slice(0, 4)}`;
