  let rs = null; try { rs = await env.DB.batch(st); } catch (e) { rs = null; } if (!Array.isArray(rs) || rs.length !== st.length || rs.some(r => !r || !Array.isArray(r.results))) { rs = []; for (const s of st) rs.push({ results: (await s.all()).results }); }
