const HOT23 = new Map(); // co -> Map(ckey -> path)
function hotKey23(co, ckey, req) { const u = new URL(req.url); let m = HOT23.get(co); if (!m) HOT23.set(co, m = new Map()); m.delete(ckey); m.set(ckey, u.pathname + u.search); while (m.size > 6) m.delete(m.keys().next().value); }
