      const phone = normPhone(x.phone); need(phone.replace(/\D/g, '').length >= 10, 'Please add your phone number so we can reach you');
      const unit = x.unit_id ? await d.one('SELECT id,name FROM units WHERE id=? AND property_id=?', +x.unit_id, p.id) : null;
      const dg = phone.replace(/\D/g, '').slice(-10);
      const ten = (await d.all(`SELECT t.id, t.phone, l.unit_id FROM tenants t JOIN leases l ON l.tenant_id=t.id JOIN units u ON u.id=l.unit_id WHERE u.property_id=? AND l.status='active'`, p.id)).find(t => String(t.phone || '').replace(/\D/g, '').slice(-10) === dg);
      const photo_ids = []; for (const fid of (x.photo_ids || []).slice(0, 8)) { const f = await d.one(`SELECT id FROM files WHERE id=? AND property_id=? AND kind='wo-pub' AND wo_id IS NULL`, +fid, p.id); if (f) photo_ids.push(f.id); }
      const name = String(x.name || '').trim().slice(0, 80);
