        await woEvent(d, w.id, who, 'fixed', `Fixed${cost != null ? ' · cost $' + (cost / 100).toFixed(2) : ''}`);
        if (String(x.note || '').trim()) await woEvent(d, w.id, who, 'note', String(x.note).trim());
        w = await woFull(d, w.id); await maintNotifyTenant(d, w, w.lang === 'es' ? `Su reparación (${w.title}) está marcada como arreglada.` : `Your repair (${w.title}) is marked fixed.`);
