async function renewalsList(d) {
  const T = todayNY();
  const rows = await d.all(`SELECT l.id lease_id, l.start, l.end, l.rent, l.mtm, l.tenant_id, t.first, t.last, p.name property, u.name unit FROM leases l JOIN units u ON u.id=l.unit_id JOIN properties p ON p.id=u.property_id JOIN tenants t ON t.id=l.tenant_id WHERE l.status='active' AND l.end IS NOT NULL AND l.end<>'' ORDER BY l.end`);
  const out = [];
  for (const r of rows) {
    const days = Math.round((Date.parse(r.end + 'T12:00:00Z') - Date.parse(T + 'T12:00:00Z')) / 864e5);
    // d70: a fixed term that rolls to month-to-month (term of 2+ months) is still a lease ending; only a pure month-to-month lease is skipped.
    // An ended lease that is still active (no renewal, no move-out) stays listed for a year; a rolled-over one for 45 days.
    const term = r.start ? Math.round((Date.parse(r.end + 'T12:00:00Z') - Date.parse(r.start + 'T12:00:00Z')) / 864e5) : 0;
    const roll = !!r.mtm && term >= 60; if (r.mtm && !roll) continue;
    if (days > 120 || days < (roll ? -45 : -365)) continue; if (roll) r.rollover = true;
    const doc = await d.one(`SELECT id,status FROM lease_docs WHERE lease_id=? AND kind='renewal' AND status<>'void' ORDER BY id DESC LIMIT 1`, r.lease_id);
    out.push({ ...r, days, stage: days < 0 ? 'ended' : days <= 30 ? '30' : days <= 60 ? '60' : days <= 90 ? '90' : '120', doc_id: doc ? doc.id : null, doc_status: doc ? doc.status : null });
  }
  return out;
}

