SCHEMA.push(`CREATE TABLE IF NOT EXISTS lease_signers(id INTEGER PRIMARY KEY, doc_id INTEGER, ord INTEGER, role TEXT, tenant_id INTEGER, name TEXT, email TEXT, phone TEXT, token TEXT, status TEXT, sent_at TEXT, viewed_at TEXT, signed_at TEXT, typed_name TEXT, sig TEXT, initials TEXT, ip TEXT, ua TEXT, reminded_at TEXT, remind_count INTEGER DEFAULT 0)`);
