const GLOBAL_TABLES = new Set(['users', 'sessions', 'orgs', 'login_fails']);
const LAZY53 = ['acquisitions', 'act32', 'ai_log', 'announcements', 'api_cache', 'applicants26', 'bank_accounts', 'bank_rules', 'bank_suggest', 'bank_txns', 'billpay34', 'bills', 'bmk45', 'budgets', 'calls', 'companies', 'cust47', 'dep37', 'entities', 'entry_audit', 'equity_moves', 'files', 'gl_accounts', 'jlines', 'jlines_orig', 'journal', 'journal_orig', 'late_fee_policies', 'leads', 'lease_charges', 'lease_docs', 'lease_signers', 'lease_templates', 'lease_tenants', 'leases', 'loan_events', 'loan_history', 'loan_properties', 'loans', 'maint_team', 'meta', 'mgmt_fees', 'moveouts26', 'owner_payouts', 'owners', 'ownreq34', 'partner_txns', 'pay45', 'pay_reports', 'payby45', 'payments', 'personal_accts', 'properties', 'property_partners', 'rb_saved', 'recon_ref', 'recurring_bills', 'rent_changes', 'sale36', 'selfhelp_log', 'settings', 'skipped_bills', 'tasks', 'tenant_invites', 'tenant_msgs', 'tenants', 'units', 'utility_accounts', 'utility_bills', 'vendors', 'vtax46', 'wo_events', 'wo_link31', 'wo_seen29', 'work_orders', 'je59', 'rb59', 'rb59p'];
let PFX = null;
async function pfxSet(rawDB) {
  if (PFX) return PFX;
  const rows = (await rawDB.prepare(`SELECT name FROM sqlite_master WHERE type='table'`).all()).results || [];
  const s = new Set(rows.map(r => r.name).filter(n => !/^c\d+_/.test(n) && !/^(_cf|sqlite_|d1_)/i.test(n) && !GLOBAL_TABLES.has(n)));
  for (const t of TABLES) if (!GLOBAL_TABLES.has(t)) s.add(t);
  for (const q of SCHEMA) { const m = /CREATE TABLE IF NOT EXISTS (\w+)/i.exec(q); if (m && !GLOBAL_TABLES.has(m[1])) s.add(m[1]); }
  // d53: tables a feature creates the first time it is used are company tables too, even before the main company has ever made them
  // (before, a new company's first use created and then read the shared, unprefixed table). Sign-in / security tables stay shared on purpose.
  for (const t of LAZY53) if (!GLOBAL_TABLES.has(t)) s.add(t);
  PFX = s; return s;
}
function rwSql(sql, co, P) {
  return String(sql)
    .replace(/\b(FROM|JOIN|INTO|UPDATE|table_info\s*\(|TABLE(?:\s+IF\s+(?:NOT\s+)?EXISTS)?|ON)(\s*)([A-Za-z_][A-Za-z0-9_]*)\b/gi, (m, kw, sp, name) => P.has(name) ? `${kw}${sp}c${co}_${name}` : m)
    .replace(/(^|[^A-Za-z0-9_.])([a-z_][a-z0-9_]*)\.(?=[a-z_*"])/g, (m, pre, name) => P.has(name) ? `${pre}c${co}_${name}.` : m);
}
function rwUsers(sql, co) {
  const s = String(sql); if (!/\b(users|sessions)\b/.test(s)) return s;
  if (/^\s*SELECT id FROM users WHERE lower\(email\)=\?\s*$/i.test(s)) return s; // emails stay unique across every company
  const cond = co > 1 ? `company_id=${co}` : `(company_id IS NULL OR company_id=1)`;
  const addWhere = (q, c) => /\bWHERE\b/i.test(q) ? q.replace(/\bWHERE\b([\s\S]*)$/i, (m, w) => `WHERE (${w}) AND ${c}`) : q + ` WHERE ${c}`;
  if (/^\s*INSERT INTO users\s*\(/i.test(s)) return s.replace(/INSERT INTO users\s*\(([^)]*)\)\s*VALUES\s*\(([^)]*)\)/i, (m, c, v) => /company_id/.test(c) ? m : `INSERT INTO users(${c},company_id) VALUES(${v},${co})`);
  if (/^\s*(UPDATE users\b|DELETE FROM users\b)/i.test(s)) return addWhere(s, cond);
  if (/^\s*DELETE FROM sessions\b/i.test(s)) return addWhere(s, `user_id IN (SELECT id FROM users WHERE ${cond})`);
  return s.replace(/\b(FROM|JOIN)\s+users\b(?:\s+(?:AS\s+)?(?!(?:WHERE|ORDER|LIMIT|GROUP|ON|JOIN|LEFT|INNER|CROSS|UNION)\b)([A-Za-z_]\w*))?/gi, (m, kw, al) => `${kw} (SELECT * FROM users WHERE ${cond}) ${al || 'users'}`);
}
function scopedEnv(env, co, P) {
  const raw = env.DB;
  const rw = sql => rwUsers(co > 1 ? rwSql(sql, co, P) : sql, co);
  const DB = { prepare: sql => { if (WRITE_RE23.test(sql) && !NOBUMP_RE23.test(sql)) MCTX.wrote = (MCTX.wrote || 0) + 1; return raw.prepare(rw(sql)); }, batch: st => raw.batch(st), exec: sql => { MCTX.wrote = (MCTX.wrote || 0) + 1; return raw.exec(rw(sql)); }, dump: () => { throw new Error('not available'); } };
  return { ...env, DB, RAW_DB: raw, CO: co };
}
