    if (!young) { console.error('co lock: company', CO_LOCK.co, 'held', CO_LOCK.n, 'x for over', +globalThis.PM_CO_STALE_MS || CO_STALE53, 'ms with no release; taken over by company', co); CO_LOCK.n = 0; CO_LOCK.h.clear(); break; }
    await new Promise(r => { let done = false; const go = () => { if (!done) { done = true; clearTimeout(tm); r(); } }; const tm = setTimeout(go, 1000); CO_LOCK.q.push(go); });
