  for (const a of DEFAULT_ACCTS) st.push(raw.prepare(`INSERT OR IGNORE INTO c${co}_gl_accounts(id,code,name,type,active) VALUES(?,?,?,?,1)`).bind(a[0], a[1], a[2], a[3]));
