    st.push(raw.prepare('INSERT INTO users(email,name,role,pass,salt,tenant_id,owner_id,created,company_id) VALUES(?,?,?,?,?,?,?,?,?)').bind(login.email, login.name, 'manager', login.pass, login.salt, null, null, nowISO(), co));
