  if (f.top_expenses.length) out.push(`Biggest costs: ${f.top_expenses.map(e => `${e.label} ${m$(e.amount)}`).join(', ')}.`);
  if (f.rent_charged) out.push(`Rent & charges billed ${m$(f.rent_charged)}, collected ${m$(f.rent_collected)} (${Math.round(f.rent_collected / f.rent_charged * 100)}%).`);
  out.push(f.owe_count ? `${f.owe_count} tenants owe ${m$(f.owe_total)} in total.` : 'Nobody owes rent.');
