// ---------- v17: owner withdrawals & money put in (source-tagged equity moves) ----------
SCHEMA.push(
  `CREATE TABLE IF NOT EXISTS equity_moves(id INTEGER PRIMARY KEY, dir TEXT, journal_id INTEGER, bank_txn_id INTEGER, date TEXT, amount INTEGER, bank_account_id INTEGER, owner_id INTEGER, person TEXT, source TEXT, purpose TEXT, scope TEXT, scope_ref TEXT, alloc TEXT, acct_label TEXT, acct_last4 TEXT, loan INTEGER DEFAULT 0, lender TEXT, loan_account_id INTEGER, note TEXT, tagged_only INTEGER DEFAULT 0, void INTEGER DEFAULT 0, created TEXT)`,
  `CREATE TABLE IF NOT EXISTS personal_accts(id INTEGER PRIMARY KEY, person TEXT, label TEXT, last4 TEXT, dir TEXT, uses INTEGER DEFAULT 0, last_used TEXT)`
);
const EM_OUT = [['profit', 'Rental profit'], ['refi', 'Refinance cash-out'], ['capital', 'Return of my own money (capital)'], ['sale', 'Sale proceeds'], ['loan_repay', 'Paying back a loan'], ['other', 'Other']];
const EM_IN = [['savings', 'Personal savings'], ['personal_loan', 'Personal loan / HELOC / credit line'], ['private_loan', 'Loan from someone (private lender / family)'], ['other_profit', 'Profit from another property'], ['other_refi', 'Refinance of another property'], ['other_sale', 'Sale of another property'], ['other', 'Other']];
const EM_PURPOSE = [['purchase', 'Purchase'], ['rehab', 'Rehab'], ['closing', 'Closing costs'], ['shortfall', 'Cover a shortfall'], ['mortgage', 'Mortgage payment'], ['other', 'Other']];
const EM_LABEL = Object.fromEntries([...EM_OUT, ...EM_IN.map(([k, l]) => ['in:' + k, l]), ...EM_PURPOSE.map(([k, l]) => ['p:' + k, l])]);
const emSrcLabel = (dir, s) => (dir === 'in' ? EM_LABEL['in:' + s] : EM_LABEL[s]) || (s ? cap1(String(s)) : 'Not tagged yet');
const EM_LOAN_ACCT = ['2650', 'Loans from owners / private lenders', 'liability'];
async function emLoanAccount(d) {
  if (AC[EM_LOAN_ACCT[0]]) return AC[EM_LOAN_ACCT[0]];
  const ex = await d.one('SELECT id FROM gl_accounts WHERE lower(name)=lower(?)', EM_LOAN_ACCT[1]); if (ex) return ex.id;
  return addGlAccount(d, { code: EM_LOAN_ACCT[0], name: EM_LOAN_ACCT[1], type: EM_LOAN_ACCT[2] });
}
async function emScopeProps(d, scope, ref) {
  if (scope === 'group') { const s = await grpProps(d, ref); return s ? [...s] : []; }
  if (scope === 'entity') return (await d.all('SELECT id FROM properties WHERE entity_id=?', +ref)).map(p => p.id);
  return [];
}
// alloc: [[property_id|null, cents], ...] summing to the amount
async function emAlloc(d, x, amount) {
  const scope = ['property', 'split', 'group', 'entity', 'none'].includes(x.scope) ? x.scope : (x.property_id ? 'property' : 'none');
  let alloc = [];
  if (scope === 'property') { need(+x.property_id, 'Choose the property'); need(await d.one('SELECT id FROM properties WHERE id=?', +x.property_id), 'Property not found'); alloc = [[+x.property_id, amount]]; }
  else if (scope === 'split') {
    const rows = (Array.isArray(x.split) ? x.split : []).map(r => [+r.property_id, cents(r.amount)]).filter(r => r[0] && r[1] > 0);
    need(rows.length >= 1, 'Pick the properties and how much for each');
    const ids = new Set((await d.all('SELECT id FROM properties')).map(p => p.id)); need(rows.every(r => ids.has(r[0])), 'Property not found');
    const tot = rows.reduce((s, r) => s + r[1], 0); need(tot === amount, `The split adds up to ${(tot / 100).toFixed(2)}, not ${(amount / 100).toFixed(2)}`);
    alloc = rows;
  } else if (scope === 'group' || scope === 'entity') {
    need(x.scope_ref, scope === 'group' ? 'Choose the group' : 'Choose the owner entity');
    alloc = [[null, amount]];
  } else alloc = [[null, amount]];
  return { scope, scope_ref: scope === 'group' || scope === 'entity' ? String(x.scope_ref) : null, alloc };
}
async function emRemember(d, person, label, last4, dir) {
  label = String(label || '').trim().slice(0, 60); last4 = String(last4 || '').replace(/\D/g, '').slice(-4);
  if (!label && !last4) return;
  const ex = await d.one('SELECT id FROM personal_accts WHERE lower(COALESCE(person,\'\'))=lower(?) AND lower(COALESCE(label,\'\'))=lower(?) AND COALESCE(last4,\'\')=?', person || '', label, last4);
  if (ex) await d.run('UPDATE personal_accts SET uses=uses+1, last_used=? WHERE id=?', nowISO(), ex.id);
  else await d.run('INSERT INTO personal_accts(person,label,last4,dir,uses,last_used) VALUES(?,?,?,?,1,?)', person || null, label || null, last4 || null, dir, nowISO());
}
async function emPerson(d, x) {
  let owner = +x.owner_id ? await d.one('SELECT id, name FROM owners WHERE id=?', +x.owner_id) : null;
  const person = String(x.person || owner?.name || '').trim().slice(0, 80);
  need(person, x.dir === 'in' ? 'Who put the money in?' : 'Who took the money out?');
  if (!owner) owner = await d.one('SELECT id, name FROM owners WHERE lower(name)=lower(?)', person);
  return { owner_id: owner ? owner.id : null, person };
}
// record one withdrawal / contribution. opt.bank_txn: a bank line being booked; opt.journal_id: tag an existing entry only (no posting)
