  const loan = dir === 'in' && (x.loan === true || x.loan === 'on' || x.loan === 1 || x.loan === '1') && ['personal_loan', 'private_loan'].includes(source) ? 1 : 0;
  const lender = String(x.lender || '').trim().slice(0, 80) || null;
