    const eqLines = alloc.map(([pid, v]) => dir === 'in' ? [eq, 0, v, 'b', pid] : [eq, v, 0, 'b', pid]);
    const bankLine = dir === 'in' ? [ba.account_id, amount, 0, 'b', alloc.length === 1 ? alloc[0][0] : null] : [ba.account_id, 0, amount, 'b', alloc.length === 1 ? alloc[0][0] : null];
    const to = [acctLabel, last4 ? '••' + last4 : ''].filter(Boolean).join(' ');
    const what = dir === 'in' ? (loan ? 'Loan in' : 'Money put in') : (source === 'capital' ? 'Return of capital' : source === 'loan_repay' ? 'Loan repayment' : 'Owner draw');
    const memo = String(x.memo || '').trim().slice(0, 120) || `${what} · ${emSrcLabel(dir, source)} · ${person}${to ? (dir === 'in' ? ' from ' : ' → ') + to : ''}`;
    jid = await post(d, { date, kind: dir === 'in' ? 'contribution' : 'owner_draw', amount, owner_id, property_id: alloc.length === 1 ? alloc[0][0] : null, bank_account_id: ba.id, _bankGl: ba.account_id, method: String(x.method || (bt ? 'Bank feed' : 'Transfer')).slice(0, 30), reconciled: bt ? 1 : 0, memo, jtype: what, payee: person, lines: [...eqLines, bankLine], _custom: 1, company_id: ba.company_id || null });
