    if (!pid) continue;
    const pp = await d.one('SELECT 1 x FROM property_partners pp JOIN properties p ON p.id=pp.property_id WHERE pp.property_id=? AND pp.owner_id=? AND p.partners_on=1', pid, owner_id);
    if (!pp) continue;
    const kind = dir === 'in' ? 'contribution' : (source === 'capital' ? 'repayment' : source === 'loan_repay' ? null : 'distribution');
    if (kind) await d.run('INSERT INTO partner_txns(property_id,owner_id,date,amount,kind,source,bank_account_id,journal_id,memo,void,created) VALUES(?,?,?,?,?,?,?,?,?,0,?)', pid, owner_id, date, v, kind, 'personal', bt ? bt.bank_account_id : (+x.bank_account_id || null), jid, `${emSrcLabel(dir, source)}`, nowISO());
