async function emList(d, f = {}) {
  const rows = await d.all(`SELECT m.*, j.void jvoid, j.memo jmemo, b.name bank, b.last4 bank_last4 FROM equity_moves m LEFT JOIN journal j ON j.id=m.journal_id LEFT JOIN bank_accounts b ON b.id=m.bank_account_id WHERE m.void=0 ORDER BY m.date DESC, m.id DESC`);
  const props = Object.fromEntries((await d.all('SELECT id, name, grp, entity_id FROM properties')).map(p => [p.id, p]));
  const ents = Object.fromEntries((await d.all('SELECT id, name FROM entities').catch(() => [])).map(e => [e.id, e]));
  const out = [];
  for (const m of rows) {
    if (m.jvoid) continue;
    const alloc = JSON.parse(m.alloc || '[]');
    const where = m.scope === 'group' ? ((GROUPS.find(g => g[0] === m.scope_ref) || [0, m.scope_ref])[1]) : m.scope === 'entity' ? (ents[+m.scope_ref]?.name || 'Owner entity') : m.scope === 'split' ? alloc.map(([p]) => props[p]?.name || '?').join(', ') : alloc[0] && alloc[0][0] ? (props[alloc[0][0]]?.name || '?') : 'No specific property';
    out.push({ id: m.id, dir: m.dir, date: m.date, amount: m.amount, person: m.person, owner_id: m.owner_id, source: m.source, source_label: emSrcLabel(m.dir, m.source), purpose: m.purpose, purpose_label: m.purpose ? EM_LABEL['p:' + m.purpose] : null, scope: m.scope, scope_ref: m.scope_ref, where, alloc: alloc.map(([p, v]) => ({ property_id: p, property: p ? props[p]?.name : null, amount: v })), acct_label: m.acct_label, acct_last4: m.acct_last4, bank: m.bank ? `${m.bank}${m.bank_last4 && !String(m.bank).includes(m.bank_last4) ? ' ••' + m.bank_last4 : ''}` : null, bank_account_id: m.bank_account_id, journal_id: m.journal_id, loan: m.loan, lender: m.lender, note: m.note, tagged_only: m.tagged_only, memo: m.jmemo });
  }
  return out;
}
function emFilter(list, f) {
  const has = (arr, v) => !arr || !arr.length || arr.map(String).includes(String(v));
  return list.filter(m => (!f.dir || m.dir === f.dir) && (!f.from || m.date >= f.from) && (!f.to || m.date <= f.to) && has(f.people, m.person) && has(f.sources, m.source) && (!f.property_ids?.length || m.alloc.some(a => has(f.property_ids, a.property_id))));
}
function emGroup(list, g, f = {}) {
  const map = new Map();
  const add = (k, label, v, m) => { const r = map.get(k) || { key: k, label, total: 0, n: 0, by_source: {} }; r.total += v; r.n++; r.by_source[m.source] = (r.by_source[m.source] || 0) + v; map.set(k, r); };
  for (const m of list) {
    if (g === 'property') { for (const a of m.alloc) { if (f.property_ids?.length && !f.property_ids.map(String).includes(String(a.property_id))) continue; add(a.property_id ? 'p' + a.property_id : 's:' + m.where, a.property || (m.scope === 'group' || m.scope === 'entity' ? m.where + ' (whole group)' : 'No specific property'), a.amount, m); } }
    else if (g === 'person') add(m.person.toLowerCase(), m.person, m.amount, m);
    else if (g === 'source') add(m.source, m.source_label, m.amount, m);
    else if (g === 'purpose') add(m.purpose || 'other', m.purpose_label || 'Other', m.amount, m);
    else if (g === 'month') add(m.date.slice(0, 7), monthLabel(m.date.slice(0, 7)), m.amount, m);
    else if (g === 'year') add(m.date.slice(0, 4), m.date.slice(0, 4), m.amount, m);
    else add('all', 'Total', m.amount, m);
  }
  const rows = [...map.values()];
  rows.sort((a, b) => g === 'month' || g === 'year' ? b.key.localeCompare(a.key) : b.total - a.total);
  return rows;
}
async function emCandidates(d) {
  // 1) entries already on the owner draw / contribution accounts that were never tagged (tag only, books unchanged)
  const tagged = new Set((await d.all('SELECT journal_id FROM equity_moves WHERE void=0 AND journal_id IS NOT NULL')).map(r => r.journal_id));
  const eqIds = [AC['3100'], AC['3200']].filter(Boolean);
  const ents = eqIds.length ? await d.all(`SELECT j.id, j.date, j.kind, j.memo, j.payee, j.amount, j.property_id, j.owner_id, j.bank_account_id, p.name property, SUM(jl.debit) dr, SUM(jl.credit) cr FROM journal j JOIN jlines jl ON jl.journal_id=j.id AND jl.account_id IN (${eqIds.map(() => '?').join(',')}) LEFT JOIN properties p ON p.id=j.property_id WHERE j.void=0 GROUP BY j.id ORDER BY j.date DESC LIMIT 400`, ...eqIds) : [];
  const entries = ents.filter(e => !tagged.has(e.id)).map(e => ({ kind: 'entry', id: e.id, date: e.date, amount: Math.abs((e.dr || 0) - (e.cr || 0)) || e.amount, dir: (e.dr || 0) >= (e.cr || 0) ? 'out' : 'in', text: e.memo || e.payee || (e.kind === 'contribution' ? 'Owner contribution' : 'Owner draw'), property: e.property, property_id: e.property_id, owner_id: e.owner_id, bank_account_id: e.bank_account_id }));
  // 2) bank lines not booked yet that look like money to / from a personal account
  const owners = (await d.all('SELECT name FROM owners')).map(o => o.name).concat((await d.all('SELECT members FROM entities').catch(() => [])).flatMap(e => { try { return JSON.parse(e.members || '[]').map(m => m.name); } catch (er) { return []; } }));
  const words = [...new Set(owners.flatMap(n => String(n || '').toLowerCase().split(/\s+/)).filter(w => w.length >= 4 && !/^(llc|inc|corp|holdings|partnership|street|avenue|general|management|company|group)$/.test(w)))];
  const NOTPERSONAL = /payroll|credit crd|card|epay|mortgage|loan pmt|insurance|irs|tax/i;
  const PERSONAL = /\b(zelle|venmo|cash ?app|paypal|online (banking )?transfer|transfer (to|from)|xfer|wire (to|from)|withdrawal|atm|owner|draw|personal|to sav|to chk|savings)\b/i;
  const lines = await d.all(`SELECT bt.id, bt.date, bt.amount, bt.description, bt.bank_account_id, b.name bank, b.last4, b.kind, s.type stype FROM bank_txns bt JOIN bank_accounts b ON b.id=bt.bank_account_id LEFT JOIN bank_suggest s ON s.txn_id=bt.id WHERE bt.status='unmatched' AND b.kind!='card' ORDER BY bt.date DESC LIMIT 3000`);
  const bank = lines.filter(l => (l.stype !== 'transfer' && l.stype !== 'match' && l.stype !== 'payment' && l.stype !== 'loan' && l.stype !== 'bill') && !NOTPERSONAL.test(l.description || '') && (PERSONAL.test(l.description || '') || words.some(w => (l.description || '').toLowerCase().includes(w))) && Math.abs(l.amount) >= 5000)
    .slice(0, 200).map(l => ({ kind: 'bank', id: l.id, date: l.date, amount: Math.abs(l.amount), dir: l.amount < 0 ? 'out' : 'in', text: String(l.description || '').replace(/\s+/g, ' ').slice(0, 120), bank: `${l.bank}${l.last4 && !String(l.bank).includes(l.last4) ? ' ••' + l.last4 : ''}`, bank_account_id: l.bank_account_id }));
  return { entries, bank };
}
// per-house totals for the deal summary (what was actually taken out / put in, by source)
async function emPropSummary(d, pid) {
  try {
    const rows = await d.all(`SELECT m.dir, m.source, m.purpose, m.alloc FROM equity_moves m LEFT JOIN journal j ON j.id=m.journal_id WHERE m.void=0 AND COALESCE(j.void,0)=0 AND m.alloc LIKE ?`, `%[${pid},%`);
    const out = { out: {}, in: {}, out_total: 0, in_total: 0, n: 0 };
    for (const m of rows) for (const [p, v] of JSON.parse(m.alloc || '[]')) if (p === pid) { out[m.dir][m.source] = (out[m.dir][m.source] || 0) + v; out[m.dir + '_total'] += v; out.n++; }
    return out;
  } catch (e) { return null; }
}
async function emRoute(env, d, user, parts, req, url) {
  const M = req.method, [, b, c] = parts; const qp = k => url.searchParams.get(k);
  if (!b && M === 'GET') {
    const f = { dir: qp('dir') || null, from: qp('from') || null, to: qp('to') || null, people: (qp('people') || '').split('|').filter(Boolean), sources: (qp('sources') || '').split('|').filter(Boolean), property_ids: (qp('property_ids') || '').split(',').filter(Boolean) };
    const all = await emList(d); const list = emFilter(all, f);
    const g = qp('group') || 'person';
    const outs = list.filter(m => m.dir === 'out'), ins = list.filter(m => m.dir === 'in');
    const loans = {}; for (const m of all) { if (!m.loan && m.source !== 'loan_repay') continue; const k = (m.lender || m.person).toLowerCase(); const L = loans[k] || (loans[k] = { lender: m.lender || m.person, borrowed: 0, repaid: 0 }); if (m.dir === 'in') L.borrowed += m.amount; else L.repaid += m.amount; }
    const cand = await emCandidates(d);
    return J({ list, groups: emGroup(f.dir ? list : outs, g, f), groups_in: f.dir ? null : emGroup(ins, g, f), totals: { out: outs.reduce((s, m) => s + m.amount, 0), in: ins.reduce((s, m) => s + m.amount, 0), out_n: outs.length, in_n: ins.length }, by_source_out: emGroup(outs, 'source'), by_source_in: emGroup(ins, 'source'), loans: Object.values(loans).map(L => ({ ...L, open: L.borrowed - L.repaid })).filter(L => L.borrowed), to_tag: { entries: cand.entries.length, bank: cand.bank.length }, people: [...new Set(all.map(m => m.person))].sort() });
  }
  if (b === 'meta' && M === 'GET') {
    const owners = await d.all('SELECT id, name FROM owners ORDER BY name');
    const ents = await d.all('SELECT id, name, members FROM entities ORDER BY name').catch(() => []);
    const members = [...new Set(ents.flatMap(e => { try { return JSON.parse(e.members || '[]').map(m => String(m.name || '').trim()); } catch (er) { return []; } }).filter(Boolean))];
    const people = []; const seen = new Set();
    for (const o of owners) { const k = o.name.toLowerCase(); if (!seen.has(k)) { seen.add(k); people.push({ owner_id: o.id, name: o.name }); } }
    for (const n of members) { const k = n.toLowerCase(); if (!seen.has(k)) { seen.add(k); people.push({ owner_id: null, name: n }); } }
    for (const r of await d.all('SELECT DISTINCT person FROM equity_moves WHERE void=0')) { const k = String(r.person || '').toLowerCase(); if (k && !seen.has(k)) { seen.add(k); people.push({ owner_id: null, name: r.person }); } }
    const banks = await d.all(`SELECT id, name, institution, last4, kind FROM bank_accounts WHERE kind!='other' ORDER BY CASE kind WHEN 'bank' THEN 0 ELSE 1 END, id`);
    const props = await d.all('SELECT id, name, grp, entity_id FROM properties ORDER BY name');
    const accts = await d.all('SELECT * FROM personal_accts ORDER BY uses DESC, last_used DESC LIMIT 40');
    const grpUsed = (await d.all(`SELECT DISTINCT grp FROM properties WHERE grp IS NOT NULL AND grp<>''`)).length > 0;
    const loans = {}; for (const m of await d.all(`SELECT dir, lender, person, amount, loan, source FROM equity_moves WHERE void=0 AND (loan=1 OR source='loan_repay')`)) { const k = (m.lender || m.person || '').toLowerCase(); const L = loans[k] || (loans[k] = { lender: m.lender || m.person, open: 0 }); L.open += m.dir === 'in' ? m.amount : -m.amount; }
    return J({ out_sources: EM_OUT, in_sources: EM_IN, purposes: EM_PURPOSE, people, banks: banks.map(x => ({ id: x.id, kind: x.kind, name: `${x.name}${x.last4 && !String(x.name).includes(x.last4) ? ' ••' + x.last4 : ''}` })), properties: props.map(p => ({ id: p.id, name: p.name, grp: grpOf(p), entity_id: p.entity_id })), groups: grpUsed ? GROUPS : [], entities: ents.map(e => ({ id: e.id, name: e.name })), accounts: accts, loans: Object.values(loans).filter(L => L.open > 0) });
  }
  if (b === 'candidates' && M === 'GET') return J(await emCandidates(d));
  if (b === 'cash' && M === 'GET') return J(await emCashByHouse(d, qp('property_id') ? +qp('property_id') : null));
  if (!b && M === 'POST') {
    const x = await body(req);
    if (x.bank_txn_id) { const bt = await d.one('SELECT * FROM bank_txns WHERE id=?', +x.bank_txn_id); need(bt && bt.status === 'unmatched', 'That bank line is already booked'); return J(await emRecord(d, x, { bank_txn: bt })); }
    if (x.journal_id) { const j = await d.one('SELECT * FROM journal WHERE id=? AND void=0', +x.journal_id); need(j, 'Entry not found'); return J(await emRecord(d, { ...x, amount: (x.amount_cents || j.amount) / 100, date: j.date, bank_account_id: j.bank_account_id }, { journal_id: j.id })); }
    return J(await emRecord(d, x));
  }
  if (b && c === 'retag' && M === 'POST') {
    // change the source / purpose / note of a recorded move (the books keep the same amounts and accounts)
    const x = await body(req); const m = await d.one('SELECT * FROM equity_moves WHERE id=? AND void=0', +b); need(m, 'Not found', 404);
    const list = m.dir === 'in' ? EM_IN : EM_OUT; need(list.some(s => s[0] === x.source), 'Choose a source');
    const eqChange = m.dir === 'out' && !m.tagged_only && ((m.source === 'capital') !== (x.source === 'capital') || (m.source === 'loan_repay') !== (x.source === 'loan_repay'));
    need(!eqChange, 'Switching to or from "return of my own money" or "paying back a loan" changes the books: delete this one and enter it again');
    await d.run('UPDATE equity_moves SET source=?, purpose=?, note=? WHERE id=?', x.source, m.dir === 'in' ? (EM_PURPOSE.some(p => p[0] === x.purpose) ? x.purpose : m.purpose) : null, String(x.note ?? m.note ?? '').slice(0, 300) || null, m.id);
    return J({ ok: true });
  }
  if (b && c === 'delete' && M === 'POST') {
    const m = await d.one('SELECT * FROM equity_moves WHERE id=? AND void=0', +b); need(m, 'Not found', 404);
    await d.run('UPDATE equity_moves SET void=1 WHERE id=?', m.id);
    if (!m.tagged_only && m.journal_id) { await voidJournal(d, m.journal_id); await d.run('UPDATE partner_txns SET void=1 WHERE journal_id=?', m.journal_id); }
    return J({ ok: true, untagged_only: !!m.tagged_only });
  }
  return null;
}

// each property's cash inside shared bank accounts: money in minus money out on the bank lines tagged to that property (never blocks anything)
async function emCashByHouse(d, onlyPid) {
  const banks = await d.all('SELECT id, name, last4, account_id, kind FROM bank_accounts WHERE account_id IS NOT NULL');
  const bankGl = banks.filter(b => b.kind !== 'card').map(b => b.account_id); if (!bankGl.length) return { rows: [], total: 0 };
  const rows = await d.all(`SELECT COALESCE(jl.property_id, j.property_id) pid, jl.account_id a, SUM(jl.debit) din, SUM(jl.credit) dout FROM jlines jl JOIN journal j ON j.id=jl.journal_id WHERE j.void=0 AND jl.basis IN ('b','c') AND jl.account_id IN (${bankGl.map(() => '?').join(',')}) ${onlyPid ? 'AND COALESCE(jl.property_id, j.property_id)=?' : ''} GROUP BY pid, jl.account_id`, ...bankGl, ...(onlyPid ? [onlyPid] : []));
  const props = Object.fromEntries((await d.all('SELECT id, name FROM properties')).map(p => [p.id, p]));
  const bn = Object.fromEntries(banks.map(b => [b.account_id, `${b.name}${b.last4 && !String(b.name).includes(b.last4) ? ' ••' + b.last4 : ''}`]));
  const by = {};
  for (const r of rows) { const k = r.pid || 0; const x = by[k] || (by[k] = { property_id: r.pid || null, property: r.pid ? (props[r.pid]?.name || '?') : 'Not tied to a property', cash_in: 0, cash_out: 0, banks: [] }); x.cash_in += r.din || 0; x.cash_out += r.dout || 0; x.banks.push({ bank: bn[r.a] || '?', net: (r.din || 0) - (r.dout || 0) }); }
  const out = Object.values(by).map(x => ({ ...x, net: x.cash_in - x.cash_out, covered: Math.max(0, x.cash_out - x.cash_in) })).sort((a, b) => a.net - b.net);
  return { rows: out, total: out.reduce((s, x) => s + x.net, 0), covered_total: out.filter(x => x.property_id).reduce((s, x) => s + x.covered, 0) };
}

// ---------- v18: management-company mode (clients, agreements, monthly fees, pay owners, owner portal) ----------
SCHEMA.push(
  `CREATE TABLE IF NOT EXISTS owner_payouts(id INTEGER PRIMARY KEY, owner_id INTEGER, month TEXT, date TEXT, amount INTEGER, method TEXT, ref TEXT, bank_account_id INTEGER, journal_id INTEGER, file_id INTEGER, summary TEXT, void INTEGER DEFAULT 0, created TEXT)`,
  `CREATE TABLE IF NOT EXISTS mgmt_fees(id INTEGER PRIMARY KEY, owner_id INTEGER, month TEXT, kind TEXT, property_id INTEGER, amount INTEGER, basis TEXT, journal_id INTEGER, void INTEGER DEFAULT 0, created TEXT)`
);
const mgmtReady = new Set();
async function ensureMgmt(d) {
  const co = MCTX.co || 1; if (mgmtReady.has(co)) return;
  const want = { owners: ['client INTEGER DEFAULT 0', 'agreement TEXT'], properties: ['managed INTEGER DEFAULT 0'], files: ['owner_id INTEGER', 'owner_share INTEGER DEFAULT 0'] };
  for (const [t, cols] of Object.entries(want)) {
    const have = new Set((await d.all(`PRAGMA table_info(${t})`)).map(r => r.name));
    for (const c of cols) if (!have.has(c.split(' ')[0])) await d.run(`ALTER TABLE ${t} ADD COLUMN ${c}`);
  }
  mgmtReady.add(co);
}
const AGR_DEFAULT = { fee_type: 'pct', fee_pct: 8, fee_flat: 0, fee_min: 0, leasing_type: 'pct', leasing_pct: 50, leasing_flat: 0, markup_pct: 0, reserve: 0, payout_method: 'ACH', bank_account_id: null };
function agrOf(o) { let a = {}; try { a = JSON.parse(o && o.agreement || '{}') || {}; } catch (e) { } const out = { ...AGR_DEFAULT, ...a }; if (!(o && o.agreement) && o && o.fee_pct) out.fee_pct = +o.fee_pct; return out; }
async function mgmtOn(d) { const s = await getSettings(d); return s.mgmt_mode === '1'; }
// d54: an owner's own terms per field. A blank field (null) uses the company default (Settings › Management fees), then the built-in default.
// Terms saved before d54 carry no t54 mark: their fee is theirs (as before); a minimum of 0 / leasing 50% of first month were the built-in values filled in for every owner, so those read as blank.
const T54G = { fee: ['fee_type', 'fee_pct', 'fee_flat'], min: ['fee_min'], leasing: ['leasing_type', 'leasing_pct', 'leasing_flat'], late: ['late_share_pct'] };
function own54(raw) {
  const r = raw || {}; const has = k => r[k] !== null && r[k] !== undefined && r[k] !== '';
  if (r.t54) return { fee: has('fee_type') && (r.fee_type === 'flat' ? has('fee_flat') : has('fee_pct')), min: has('fee_min'), leasing: has('leasing_type'), late: has('late_share_pct') };
  return { fee: true, min: has('fee_min') && +r.fee_min !== 0, leasing: has('leasing_type') && !(r.leasing_type === 'pct' && (+r.leasing_pct === 50 || !has('leasing_pct'))), late: has('late_share_pct') };
}
function agrMerge54(o, def) {
  if (!(o && o.agreement)) return { ...agrOf(o), ...(def || {}) };
  let raw = {}; try { raw = JSON.parse(o.agreement) || {}; } catch (e) { raw = {}; }
  const base = { ...AGR_DEFAULT, ...(def || {}) }; const out = { ...base };
  for (const [k, v] of Object.entries(raw)) { if (Object.values(T54G).some(g => g.includes(k))) continue; if (v !== null && v !== undefined) out[k] = v; }
  const set = own54(raw);
  for (const [g, keys] of Object.entries(T54G)) if (set[g]) for (const k of keys) { if (raw[k] !== null && raw[k] !== undefined && raw[k] !== '') out[k] = raw[k]; else if (g === 'fee' || g === 'leasing') out[k] = AGR_DEFAULT[k] ?? 0; }
  if (out.late_share_pct == null) out.late_share_pct = 0;
  out.src54 = Object.fromEntries(Object.keys(T54G).map(g => [g, set[g] ? 'owner' : 'company']));
  return out;
}
// the late-fee part of each tenant payment in a month (from the payment's own split), by payment and by property
async function lateParts54(d, ids, from, to) {
  const out = { byProp: {}, byPay: new Map(), anySplit: false, pays: [] }; if (!ids.length) return out;
  for (let i = 0; i < ids.length; i += 80) { const ch = ids.slice(i, i + 80); out.pays.push(...await d.all(`SELECT id, property_id FROM journal WHERE void=0 AND kind='payment' AND date>=? AND date<=? AND property_id IN (${ch.map(() => '?').join(',')})`, from, to, ...ch)); }
  if (!out.pays.length) return out;
  let sp = new Map(); try { if (typeof splits45 === 'function') sp = await splits45(d, out.pays.map(p => p.id)); } catch (e) { sp = new Map(); }
  for (const p of out.pays) { const s = sp.get(p.id); if (!s || !Array.isArray(s.list) || !s.list.length) continue; out.anySplit = true; let v = 0; for (const x of s.list) if (x.type === 'Late fee') v += x.amount;
    if (v > 0) { out.byPay.set(p.id, v); out.byProp[p.property_id] = (out.byProp[p.property_id] || 0) + v; } }
  return out;
}

const REPAIR_RX = /repair|maint|plumb|electric|hvac|heat|roof|paint|applian|clean|landscap|lawn|snow|pest|handyman|turnover|locks?|door|window|floor/i;
async function mgmtClients(d) { return d.all('SELECT * FROM owners WHERE client=1 ORDER BY name'); }
// what this client owes in fees for one month (management % or flat per door with a minimum, leasing fees, repair markup)
async function mgmtFeeCalc(d, owner, month) {
  const MG53 = await mgfeeAll53(d); // d53: company default (owners with no terms of their own) + per-house overrides + late-fee share
  const a = agrMerge54(owner, MG53.def); const aP = pid => (MG53.props[pid] ? { ...a, ...MG53.props[pid] } : a);
  const props = await d.all('SELECT p.id, p.name, (SELECT COUNT(*) FROM units u WHERE u.property_id=p.id) doors FROM properties p WHERE p.owner_id=? AND COALESCE(p.managed,0)=1 ORDER BY p.name', owner.id);
  if (!props.length) return { lines: [], total: 0, posted: 0, pending: 0, collected: 0, doors: 0 };
  const ids = props.map(p => p.id), ph = ids.map(() => '?').join(','), from = month + '-01', to = monthEnd(month);
  const inc = await d.all(`SELECT property_id, SUM(amount) a FROM journal WHERE void=0 AND kind IN ('payment','other_income') AND date>=? AND date<=? AND property_id IN (${ph}) GROUP BY property_id`, from, to, ...ids);
  const im = Object.fromEntries(inc.map(r => [r.property_id, r.a || 0]));
  // d54: late fees are not part of "% of rent collected" (management's share of late fees is its own line below)
  const LP = await lateParts54(d, ids, from, to); for (const [pid, v] of Object.entries(LP.byProp)) if (im[pid] != null) im[pid] = Math.max(0, im[pid] - v);
  const lines = [];
  let mg = 0;
  for (const p of props) { const a = aP(p.id); const col = im[p.id] || 0; const fee = a.fee_type === 'flat' ? (p.doors || 1) * Math.round(+a.fee_flat || 0) : Math.round(col * (+a.fee_pct || 0) / 100); mg += fee; lines.push({ kind: 'mgmt', property_id: p.id, property: p.name, basis: a.fee_type === 'flat' ? `${p.doors || 1} door${(p.doors || 1) === 1 ? '' : 's'} × ${(+a.fee_flat / 100).toFixed(2)}` : `${a.fee_pct}% of ${(col / 100).toFixed(2)} collected${LP.byProp[p.id] ? `, not counting ${(LP.byProp[p.id] / 100).toFixed(2)} late fees` : ''}`, amount: fee, collected: col }); }
  const minFee = Math.round(+a.fee_min || 0);
  if (minFee && mg < minFee) { const add = minFee - mg; const l0 = lines.find(l => l.kind === 'mgmt'); l0.amount += add; l0.basis += ` (raised to the ${(minFee / 100).toFixed(2)} minimum)`; mg = minFee; }
  // leasing fee: leases that started this month
  const newL = await d.all(`SELECT l.id, l.rent, l.start, u.property_id, u.name unit, t.first, t.last FROM leases l JOIN units u ON u.id=l.unit_id LEFT JOIN tenants t ON t.id=l.tenant_id WHERE u.property_id IN (${ph}) AND l.start>=? AND l.start<=?`, ...ids, from, to);
  for (const l of newL) { const a = aP(l.property_id); if (a.leasing_type === 'none') continue; const fee = a.leasing_type === 'flat' ? Math.round(+a.leasing_flat || 0) : Math.round((l.rent || 0) * (+a.leasing_pct || 0) / 100); if (fee > 0) lines.push({ kind: 'leasing', property_id: l.property_id, property: props.find(p => p.id === l.property_id)?.name, basis: `New lease ${l.first || ''} ${l.last || ''} · ${l.unit}${a.leasing_type === 'flat' ? '' : ` · ${a.leasing_pct}% of ${((l.rent || 0) / 100).toFixed(2)}`}`, amount: fee }); }
  // d53/d54: late-fee share — management keeps this % of the late fees collected from tenants this month (each payment's own split; late fees charged only for old payments that carry no split)
  try { const shareP = props.filter(p => +aP(p.id).late_share_pct > 0); if (shareP.length) { const sid = shareP.map(p => p.id); const sph = sid.map(() => '?').join(',');
    const lfBy = { ...LP.byProp }; let basisW = 'collected';
    if (!LP.anySplit && LP.pays.some(p => sid.includes(p.property_id))) { basisW = 'charged'; for (const r of await d.all(`SELECT property_id, SUM(amount) a FROM journal WHERE void=0 AND kind='latefee' AND date>=? AND date<=? AND property_id IN (${sph}) GROUP BY property_id`, from, to, ...sid)) lfBy[r.property_id] = r.a || 0; }
    for (const p of shareP) { const v = lfBy[p.id] || 0; const pc = +aP(p.id).late_share_pct; const fee = Math.round(v * pc / 100); if (fee > 0) lines.push({ kind: 'latefee', property_id: p.id, property: p.name, basis: `${pc >= 100 ? 'Management keeps' : pc + '% of'} ${(v / 100).toFixed(2)} late fees ${basisW}`, amount: fee, late_total: v }); } } } catch (e) { console.error('late share', e && e.message); }
  // markup on repairs paid this month
  if (+a.markup_pct > 0) {
    const ex = await d.all(`SELECT j.property_id, j.amount, j.account_id, j.memo, v.name vendor FROM journal j LEFT JOIN vendors v ON v.id=j.vendor_id WHERE j.void=0 AND j.kind='expense' AND j.date>=? AND j.date<=? AND j.property_id IN (${ph})`, from, to, ...ids);
    const byP = {}; for (const e of ex) { const an = ACBYID[e.account_id]?.name || ''; if (!REPAIR_RX.test(an + ' ' + (e.memo || ''))) continue; byP[e.property_id] = (byP[e.property_id] || 0) + e.amount; }
    for (const [pid, v] of Object.entries(byP)) { const fee = Math.round(v * (+a.markup_pct) / 100); if (fee > 0) lines.push({ kind: 'markup', property_id: +pid, property: props.find(p => p.id === +pid)?.name, basis: `${a.markup_pct}% markup on ${(v / 100).toFixed(2)} of repairs`, amount: fee }); }
  }
  const posted = await d.all('SELECT kind, property_id, SUM(amount) a FROM mgmt_fees WHERE owner_id=? AND month=? AND void=0 GROUP BY kind, property_id', owner.id, month);
  const pm = {}; for (const r of posted) pm[r.kind + ':' + r.property_id] = r.a;
  for (const l of lines) { const k = l.kind + ':' + l.property_id; l.posted = Math.min(l.amount, pm[k] || 0); pm[k] = (pm[k] || 0) - l.posted; l.pending = Math.max(0, l.amount - l.posted); }
  const total = lines.reduce((s, l) => s + l.amount, 0), postedT = posted.reduce((s, r) => s + r.a, 0);
  return { lines: lines.filter(l => l.amount > 0), total, posted: postedT, pending: lines.reduce((s, l) => s + l.pending, 0), collected: Object.values(im).reduce((s, v) => s + v, 0), doors: props.reduce((s, p) => s + (p.doors || 1), 0), agreement: a };
}
async function mgmtPostFees(d, owner, month, date) {
  const c = await mgmtFeeCalc(d, owner, month); const a = c.agreement || agrOf(owner);
  const bankId = +a.bank_account_id || +(await getSettings(d)).mgmt_fee_bank || (await d.one(`SELECT id FROM bank_accounts WHERE kind='bank' ORDER BY id`))?.id; need(bankId, 'Add a bank account first');
  const ba = await d.one('SELECT * FROM bank_accounts WHERE id=?', bankId);
  const label = { mgmt: 'Management fee', leasing: 'Leasing fee', markup: 'Repair markup', latefee: 'Late-fee share' };
  let n = 0, sum = 0;
  for (const l of c.lines) {
    if (!l.pending) continue;
    const jid = await post(d, { date: date || (monthEnd(month) <= todayNY() ? monthEnd(month) : todayNY()), kind: 'mgmt_fee', memo: `${label[l.kind]} · ${monthLabel(month)} · ${l.basis}`.slice(0, 160), amount: l.pending, property_id: l.property_id, owner_id: owner.id, bank_account_id: ba.id, _bankGl: ba.account_id, method: 'Transfer', ref: `MGMT-${owner.id}-${month}-${l.kind}`, jtype: label[l.kind], src: 'mgmt' });
    await d.run('INSERT INTO mgmt_fees(owner_id,month,kind,property_id,amount,basis,journal_id,void,created) VALUES(?,?,?,?,?,?,?,0,?)', owner.id, month, l.kind, l.property_id, l.pending, l.basis, jid, nowISO()); n++; sum += l.pending;
  }
  return { posted: n, amount: sum };
}
// automatic monthly fee posting (on the 1st for last month, or on the day set in Settings)
async function mgmtAuto(d, T, s) {
  if (s.mgmt_mode !== '1') return 0;
  await ensureMgmt(d);
  const when = s.mgmt_fee_when || 'close'; const day = Math.max(1, Math.min(28, +s.mgmt_fee_day || 1));
  let month; if (when === 'off') return 0;
  if (when === 'day') { if (+T.slice(8, 10) < day) return 0; month = ym(T); } else month = addMonths(ym(T), -1);
  const key = `mgmt_auto_${month}`; if (s[key]) return 0;
  let n = 0; for (const o of await mgmtClients(d)) { try { n += (await mgmtPostFees(d, o, month)).posted; } catch (e) { console.error('mgmt fee', o.id, e && e.message); } }
  await d.run('INSERT OR REPLACE INTO settings(k,v) VALUES(?,?)', key, nowISO());
  return n;
}
async function mgmtPayRow(d, o, month) {
  const st = await ownerStatement(d, o.id, month);
  const fee = await mgmtFeeCalc(d, o, month); const a = agrOf(o);
  const paid = await d.all('SELECT * FROM owner_payouts WHERE owner_id=? AND month=? AND void=0 ORDER BY id', o.id, month);
  const props = await d.all('SELECT id, name FROM properties WHERE owner_id=? ORDER BY name', o.id);
  const t = st.totals || {};
  const later = paid.filter(p => p.date > monthEnd(month)).reduce((s, p) => s + p.amount, 0); // payouts for this month dated after it
  const cash = (t.closing || 0) - later;
  const reserve = Math.round(+a.reserve || 0);
  const due = Math.max(0, cash - fee.pending - reserve);
  const login = await d.one(`SELECT email FROM users WHERE role='owner' AND owner_id=?`, o.id);
  return { owner_id: o.id, name: o.name, contact: o.contact, email: o.email, phone: o.phone, properties: props, agreement: a, opening: t.opening || 0, collected: t.income || 0, expenses: t.expenses || 0, fees_posted: t.fees || 0, fees_pending: fee.pending, fee_lines: fee.lines, draws: t.draws || 0, contributions: t.contributions || 0, cash, reserve, due, paid: paid.map(p => ({ id: p.id, date: p.date, amount: p.amount, method: p.method, ref: p.ref, file_id: p.file_id })), paid_total: paid.reduce((s, p) => s + p.amount, 0), portal: login ? login.email : null };
}
function mgmtStatementPdf(st, co, extra = {}) {
  const pdf = newPdf(); pdf.page(); const M = pdf.M, PW = pdf.PW; const $$m = c => (c < 0 ? '-$' : '$') + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  pdf.rect(0, 0, PW, 92, '0.27 0.28 0.84');
  pdf.text(M, 40, co || 'Property management', { size: 11, color: '1 1 1' }); pdf.text(M, 66, `Owner statement · ${st.label}`, { size: 20, bold: true, color: '1 1 1' });
  pdf.text(PW - M, 40, st.owner.name, { size: 11, bold: true, color: '1 1 1', align: 'right' }); pdf.text(PW - M, 58, `${st.month}-01 to ${monthEnd(st.month)}`, { size: 9, color: '0.9 0.9 1', align: 'right' });
  pdf.y = 120; const t = st.totals || {};
  const kv = [['Opening balance', t.opening || 0], ['Rent & income collected', t.income || 0], ['Expenses paid', -(t.expenses || 0)], ['Management fees', -(t.fees || 0)], ['Money you added', t.contributions || 0], ['Paid to you', -(t.draws || 0)], ['Closing balance', t.closing || 0]];
  for (const [k, v] of kv) { const last = k === 'Closing balance'; if (last) pdf.rule(M, pdf.y - 4, PW - M, 1, '0.6 0.6 0.7'); pdf.text(M, pdf.y + 10, k, { size: 11, bold: last }); pdf.text(PW - M, pdf.y + 10, $$m(v), { size: 11, bold: last, align: 'right' }); pdf.y += 20; }
  if (extra.reserve) { pdf.text(M, pdf.y + 10, `Reserve held for repairs: ${$$m(extra.reserve)}`, { size: 9.5, color: '0.4 0.4 0.5' }); pdf.y += 16; }
  if (extra.payout) { pdf.y += 4; pdf.rect(M, pdf.y, PW - 2 * M, 30, '0.9 0.97 0.93'); pdf.text(M + 12, pdf.y + 19, `Paid to you ${extra.payout.date}: ${$$m(extra.payout.amount)} by ${extra.payout.method}${extra.payout.ref ? ' · ref ' + extra.payout.ref : ''}`, { size: 10.5, bold: true, color: '0.02 0.4 0.25' }); pdf.y += 42; }
  pdf.y += 8;
  for (const p of st.properties || []) {
    pdf.need(60); pdf.text(M, pdf.y + 12, p.name, { size: 12.5, bold: true }); pdf.text(PW - M, pdf.y + 12, `income ${$$m(p.income)} · expenses ${$$m(p.expenses + p.fees)}`, { size: 9, align: 'right', color: '0.4 0.4 0.5' }); pdf.y += 18; pdf.rule(M, pdf.y, PW - M);
    pdf.y += 4;
    if (!p.lines.length) { pdf.text(M, pdf.y + 11, 'No activity this month', { size: 9.5, color: '0.5 0.5 0.55' }); pdf.y += 16; }
    for (const l of p.lines) { pdf.need(15); pdf.text(M, pdf.y + 10, l.date.slice(5).replace('-', '/'), { size: 9 }); pdf.text(M + 40, pdf.y + 10, String(l.account || '').slice(0, 30), { size: 9 }); pdf.text(M + 200, pdf.y + 10, String(l.memo || '').slice(0, 52), { size: 9, color: '0.35 0.35 0.4' }); pdf.text(PW - M, pdf.y + 10, $$m(l.amount), { size: 9, align: 'right' }); pdf.y += 14; }
    pdf.y += 10;
  }
  pdf.need(30); pdf.y += 6; pdf.text(M, pdf.y + 10, `Prepared ${todayNY()}. Questions? Reply to your property manager.`, { size: 8.5, color: '0.5 0.5 0.55' });
  return pdf.bytes();
}
async function mgmtSaveStatement(env, d, o, month, payout) {
  const st = await ownerStatement(d, o.id, month); const s = await getSettings(d);
  const bytes = mgmtStatementPdf(st, s.company, { reserve: Math.round(+agrOf(o).reserve || 0), payout });
  const key = `c${MCTX.co || 1}/d/${Date.now().toString(36)}-${randHex(8)}`;
  await env.FILES.put(key, bytes, { httpMetadata: { contentType: 'application/pdf' } });
  const name = `Owner statement ${monthLabel(month)} - ${o.name}.pdf`.replace(/[\/\\]/g, '-');
  const r = await d.run(`INSERT INTO files(key,name,ctype,size,property_id,kind,category,doc_date,title,created,src,owner_id,owner_share) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1)`, key, name, 'application/pdf', bytes.length, null, 'document', 'owner_statement', monthEnd(month) <= todayNY() ? monthEnd(month) : todayNY(), `Owner statement · ${monthLabel(month)}`, nowISO(), 'mgmt', o.id);
  return r.last_row_id;
}
async function mgmtAvailable(d, pid, amount) {
  if (!(await mgmtOn(d))) return { warn: false };
  const p = await d.one('SELECT id, name, owner_id, managed FROM properties WHERE id=?', pid); if (!p || !p.managed || !p.owner_id) return { warn: false };
  const o = await d.one('SELECT * FROM owners WHERE id=?', p.owner_id); if (!o || !o.client) return { warn: false };
  const row = await mgmtPayRow(d, o, ym(todayNY()));
  const avail = row.cash - row.fees_pending - row.reserve;
  return { warn: amount > avail, owner: o.name, available: avail, cash: row.cash, reserve: row.reserve, property: p.name, amount };
}
