    return J({ mgmt: s.mgmt_mode === '1', people: ents.filter(e => e.type === 'individual').map(e => ({ id: e.id, name: e.name })), llcs: ents.filter(e => e.type !== 'individual' && e.type !== 'partnership').map(e => ({ id: e.id, name: e.name, type: e.type })), partners: owners.filter(o => !o.client).map(o => ({ id: o.id, name: o.name })), clients: owners.filter(o => o.client).map(o => ({ id: o.id, name: o.name })), groups: used.length ? GROUPS : [] });
