    const ownerRow = async name => { const n = String(name || '').trim().slice(0, 120); if (!n) return null; const o = await d.one('SELECT id FROM owners WHERE lower(name)=lower(?)', n); return o ? o.id : (await d.run('INSERT INTO owners(name,contact,email,phone,fee_pct) VALUES(?,?,?,?,0)', n, n, '', '')).last_row_id; };
    const entRow = async (name, type, members) => { const n = String(name || '').trim().slice(0, 120); need(n, 'Enter the name'); const e = await d.one('SELECT id FROM entities WHERE lower(name)=lower(?)', n); if (e) return e.id; return (await d.run('INSERT INTO entities(name,type,address,state,tax_form,members,status,created) VALUES(?,?,?,?,?,?,?,?)', n, type, '', '', ENT_TYPES[type][1], JSON.stringify(members || []), 'confirmed', nowISO())).last_row_id; };
    let entityId = null, ownerId = null, managed = 0, partners = null;
