  for (const r of await d.all(`SELECT rb.*, v.name vendor, p.name property FROM recurring_bills rb LEFT JOIN vendors v ON v.id=rb.vendor_id LEFT JOIN properties p ON p.id=rb.property_id WHERE rb.active=1 AND rb.next_date<=? ORDER BY rb.next_date`, E)) { let nd = r.next_date, g = 0; while (nd <= E && g++ < 12) { out.push({ id: r.id, date: nd, amount: r.amount, memo: r.memo, vendor: r.vendor, property: r.property, frequency: r.frequency }); nd = advance(nd, r.frequency); } }
