  const lines = await d.all(`SELECT jl.account_id, jl.property_id, jl.debit, jl.credit, jl.memo, a.code, a.name acct, p.name property FROM jlines jl LEFT JOIN gl_accounts a ON a.id=jl.account_id LEFT JOIN properties p ON p.id=jl.property_id WHERE jl.journal_id=? AND jl.basis IN ('b','c') ORDER BY jl.id`, jid);
