  const byP = new Map(); const add = (pid, v) => byP.set(pid || null, (byP.get(pid || null) || 0) + v);
  const lines = [];
  const ufBy = new Map(); for (const r of list) { ufBy.set(r.property_id || null, (ufBy.get(r.property_id || null) || 0) + r.uf); add(r.property_id, r.uf); }
  for (const o of others) add(o.property_id, o.amount);
  for (const [pid, v] of byP) lines.push([ba.account_id, v, 0, 'b', pid]);
  for (const [pid, v] of ufBy) lines.push([AC['1100'], 0, v, 'b', pid]);
