  return { e: { date, kind: 'gl', amount: total, memo, ref: String(x.ref || '').trim().slice(0, 40) || null, bank_account_id: ba.id, bank_amount: total, method: 'Deposit', jtype: 'Deposit', property_id: pids.length === 1 && byP.size === 1 ? pids[0] : null, lines }, ids, others, total, ba };
