    try { await keepOriginal(d, editId); } catch (er) { }
    e.id = editId; e.created = old.created;
    await d.batch([d.stmt('UPDATE journal SET deposit_id=NULL WHERE deposit_id=?', editId), d.stmt('DELETE FROM jlines WHERE journal_id=?', editId), d.stmt('DELETE FROM journal WHERE id=?', editId), ...journalStmts(d, e),
      ...(ids.length ? [d.stmt(`UPDATE journal SET deposit_id=? WHERE id IN (SELECT value FROM json_each(?))`, editId, JSON.stringify(ids))] : []),
      d.stmt('INSERT OR REPLACE INTO dep37(journal_id, others, by_name, created, updated) VALUES(?,?,?,COALESCE((SELECT created FROM dep37 WHERE journal_id=?),?),?)', editId, JSON.stringify(others), by, editId, nowISO(), nowISO())]);
    jid = editId;
