    const ufNow = cur.filter(l => l.account_id === AC['1100']).reduce((s, l) => s + l.debit - l.credit, 0);
    const ufNew = lines.length ? lines.filter(l => +l.account_id === AC['1100'] && l.basis !== 'a').reduce((s, l) => s + Math.round(+l.debit || 0) - Math.round(+l.credit || 0), 0) : ufNow;
