  if (b === 'deposits' && M === 'GET') return J({ items: await depositsList37(d, +q.bank || 0, q.limit) });
  if (b === 'deposit' && !id && M === 'POST') return J(await saveDeposit37(d, user, await body(req), 0));
  if (b === 'deposit' && id && !parts[3] && M === 'GET') return J(await depositDetail37(d, id));
  if (b === 'deposit' && id && !parts[3] && M === 'POST') return J(await saveDeposit37(d, user, await body(req), id));
