  const want = (x.bills || []).map(z => ({ id: +z.id, amount: typeof z.amount === 'number' ? Math.round(z.amount) : cents(z.amount) })).filter(z => z.id);
  need(want.length, 'Pick the bill(s) this paid'); need(want.length <= 40, 'Too many bills at once');
  need(new Set(want.map(z => z.id)).size === want.length, 'A bill is picked twice');
  const open = await openBills39(d); const byId = new Map(open.filter(z => z.id).map(z => [z.id, z]));
  for (const w of want) { const o = byId.get(w.id); need(o, 'One of those bills is already paid or not found. Refresh.'); need(w.amount > 0, 'Enter the amount for each bill'); need(w.amount <= o.balance, `Bill ${o.ref || o.memo || ''} only has ${usd39(o.balance)} left`.replace('  ', ' ')); }
  const total = want.reduce((s, w) => s + w.amount, 0);
