  const bankAmt = ba ? lines.filter(l => l.account_id === ba.account_id).reduce((s, l) => s + l.debit - l.credit, 0) : 0;
  const jid = await post(d, { date, kind: 'journal', jtype: 'Gen Journal', memo, amount: dr, property_id: pids.length === 1 ? pids[0] : null, bank_account_id: ba && bankAmt ? ba.id : null, bank_amount: ba && bankAmt ? bankAmt : null, ref: String(x.ref || '').trim().slice(0, 40) || null, method: 'Journal', src: 'manual',
    lines: lines.map(l => [l.account_id, l.debit, l.credit, 'b', l.property_id, undefined, l.memo]) });
  await act32(d, user, 'Banking', `Journal entry · ${usd39(dr)} · ${lines.length} lines`, `entry ${jid}`);
