  if (/(transfer|deed|conveyance|grantor|stamp|excise|mansion)\b.*\btax|\btax\b.*\b(transfer|deed|stamps?)\b|tax stamps?|revenue stamps?|realty transfer/.test(L)) return refi ? 'loan_fees' : 'transfer_tax';
