  if (category === 'tax_proration' || (/\btax(es)?\b/.test(L) && /county|city|town|township|school|village|borough|property|real estate|municipal|ad valorem|\d{1,2}\/\d{1,2}|\btax(es)?\b\s*$|^taxes?\b/.test(L) && !/transfer|recording|record|auditor|deed|stamp|certificate|cert\b|search|service|preparation|prep\b/.test(L))) return 'property_tax';
