// ---------- d50: owner-only cleanup of uploaded files that no company points to any more (e.g. a deleted test company's PDFs) ----------
// GET fb48/orphans50?from=ISO&to=ISO  -> u/ objects uploaded in that window, each with every place in the database that still names it
// POST fb48/orphans50 {from, to, keys:[...]} -> deletes only keys that are in the window, start with u/, and are named nowhere
async function orphans50Scan(env, raw, from, to) {
  need(env.FILES, 'No file storage', 400); const f0 = Date.parse(from), t0 = Date.parse(to);
  need(Number.isFinite(f0) && Number.isFinite(t0) && t0 > f0 && t0 - f0 <= 12 * 3600e3, 'Give a from/to window of at most 12 hours', 400);
  const cands = []; let cur;
  do { const l = await env.FILES.list({ prefix: 'u/', cursor: cur, limit: 1000 }); for (const o of (l.objects || [])) { const up = o.uploaded ? new Date(o.uploaded).getTime() : NaN; if (up >= f0 && up <= t0) cands.push({ key: o.key, size: o.size, uploaded: new Date(up).toISOString(), refs: [] }); } cur = l.truncated ? l.cursor : null; } while (cur && cands.length < 50);
  need(cands.length <= 40, 'Too many files in that window; narrow it', 400);
  if (!cands.length) return cands;
  const tabs = ((await raw.prepare(`SELECT name, sql FROM sqlite_master WHERE type='table'`).all()).results) || [];
  for (const t of tabs) {
    const cols = [...String(t.sql || '').matchAll(/[(,]\s*"?([A-Za-z_][A-Za-z0-9_]*)"?\s+(TEXT|BLOB|)\b/gi)].map(m => m[1]).filter(cn => /key|file|pdf|path|url|doc|shot|attach|src/i.test(cn) && !/^(INTEGER|PRIMARY|UNIQUE|CHECK|FOREIGN)$/i.test(cn));
    if (!cols.length) continue;
    for (const cn of [...new Set(cols)]) {
      for (let i = 0; i < cands.length; i += 20) { const ch = cands.slice(i, i + 20);
        let rs = []; try { rs = ((await raw.prepare(`SELECT DISTINCT "${cn}" v FROM "${t.name}" WHERE ${ch.map(() => `instr(CAST("${cn}" AS TEXT), ?) > 0`).join(' OR ')} LIMIT 50`).bind(...ch.map(x => x.key)).all()).results) || []; } catch (e) { continue; }
        for (const r of rs) for (const x of ch) if (String(r.v || '').includes(x.key)) x.refs.push(t.name + '.' + cn); } } }
  return cands;
}
