  if (!mort.length) return res;
  let loans = []; try { loans = await d.all(`SELECT l.*, p.name property FROM loans l LEFT JOIN properties p ON p.id=l.property_id WHERE COALESCE(l.status,'')<>'merged' AND COALESCE(l.status,'')<>'paid off' ORDER BY p.name, l.id`); } catch (e) { return res; }
