    const bill = bi ? { key: k, ref: bi.ref || null, date: bi.bill_date || null, memo: bi.memo || null, amount: bi.amount } : ajr ? { key: k, ref: ajr.ref || null, date: ajr.date, memo: /^bill$/i.test(ajr.memo || '') ? null : ajr.memo, amount: ajr.amount } : null;
    const r = { vendor: j.vendor || (bi && bi.vendor) || null, date: j.date, memo: j.memo || null, account: ACBYID[j.account_id]?.name || null, bill,
      work_orders: wos.map(w => ({ id: w.id, title: w.title || null, description: w.description ? String(w.description).slice(0, 600) : null, status: w.status || null, category: w.category || null, closed: w.closed || null,
        notes: WE.filter(e => e.wo_id === w.id && e.body).slice(-4).map(e => ({ by: e.author || null, kind: e.kind, body: String(e.body).replace(/[\u{1F300}-\u{1FAFF}\u2600-\u27BF]/gu, '').trim().slice(0, 400), at: e.created })).filter(n => n.body) })),
      files, markup: mk ? { kind: mk.kind, value: mk.value, amount: mk.amount, base: mk.base, note: mk.note || null } : null };
