    const date = url.searchParams.get('date') || new Date().toISOString().slice(0, 10);
    const sps = {}; for (const L of loans) { try { sps[L.id] = L.total ? await split59(d, L, date, L.total) : null; } catch (e) { sps[L.id] = null; } }
