async function workers65(d) {
  const ws = await d.all('SELECT k.*, v.name, v.trade, v.phone vphone, v.email vemail, u.email login_email FROM wk65 k JOIN vendors v ON v.id=k.vendor_id LEFT JOIN users u ON u.id=k.user_id ORDER BY k.active DESC, v.name');
  const st = await d.all(`SELECT w.vendor_id, COUNT(*) n, SUM(CASE WHEN w.status NOT IN ('completed','closed') THEN 1 ELSE 0 END) open FROM work_orders w WHERE w.vendor_id IN (SELECT vendor_id FROM wk65) GROUP BY w.vendor_id`);
  const bl = await d.all(`SELECT b.vendor_id, SUM(b.amount - COALESCE(b.amount_paid,0)) owed FROM bills b WHERE b.status='open' AND b.vendor_id IN (SELECT vendor_id FROM wk65) GROUP BY b.vendor_id`);
  const pd = await d.all(`SELECT b.vendor_id, SUM(y.amount) paid FROM wpay65 y JOIN bills b ON b.id=y.bill_id JOIN journal j ON j.id=y.journal_id AND j.void=0 GROUP BY b.vendor_id`);
  const by = (arr, k) => Object.fromEntries(arr.map(r => [r.vendor_id, r[k] || 0]));
  const sn = by(st, 'n'), so = by(st, 'open'), ow = by(bl, 'owed'), pa = by(pd, 'paid');
  return ws.map(k => ({ id: k.id, vendor_id: k.vendor_id, name: k.name, kind: k.kind || 'contractor', trade: k.trade || '', cats: js62(k.cats || '[]'), phone: k.phone || k.vphone || '', email: k.email || k.vemail || '', login_email: k.login_email || null, active: !!k.active, jobs: sn[k.vendor_id] || 0, open_jobs: so[k.vendor_id] || 0, owed: ow[k.vendor_id] || 0, paid: pa[k.vendor_id] || 0 }));
}
