  const counts = { all: out.length, to_print: out.filter(c => c.to_print && c.status !== 'void').length, void: out.filter(c => c.status === 'void').length };
  if (bid) out = out.filter(c => c.bank_account_id === bid);
  if (st === 'print') out = out.filter(c => c.to_print && c.status !== 'void'); else if (st === 'void') out = out.filter(c => c.status === 'void'); else if (st === 'printed') out = out.filter(c => c.status === 'printed');
