  need(sum === t, sum < t ? `The lines add up to ${usd66(sum)}, the total is ${usd66(t)}. Left to split: ${usd66(t - sum)}.` : `The lines add up to ${usd66(sum)}, which is ${usd66(sum - t)} more than the total of ${usd66(t)}.`);
