async function stripeSettle69(env, d, sess) {
  const m = sess.metadata || {}; const ref = sess.payment_intent && sess.payment_intent.id ? sess.payment_intent.id : (sess.payment_intent || sess.id);
  if (await d.one('SELECT id FROM payments WHERE ref=?', ref)) return; const cfg = await cfg69(d);
  if (m.kind === 'appfee') { const ap = await d.one('SELECT * FROM app69 WHERE id=?', +m.app_id); if (!ap || ap.fee_status === 'paid') return;
    const jid = await post(d, { date: todayNY(), kind: 'other_income', memo: `Application fee - ${ap.first} ${ap.last}`, amount: +m.amount, account_id: AC['4400'] || AC['4000'], property_id: ap.property_id, bank_account_id: await bankOf69(d, ap.property_id), ref });
    await d.run(`UPDATE app69 SET fee_status='paid', fee_ref=?, fee_method='card', fee_journal_id=? WHERE id=?`, ref, jid, ap.id);
    await d.run('INSERT INTO payments(processor,status,amount,tenant_id,lease_id,method,ref,journal_id,created,meta) VALUES(?,?,?,?,?,?,?,?,?,?)', 'stripe', 'succeeded', +m.amount, null, null, 'card', ref, jid, nowISO(), JSON.stringify({ src: 'x69appfee', app_id: ap.id }));
    if (ap.status === 'draft') await submitApp69(env, d, await d.one('SELECT * FROM app69 WHERE id=?', ap.id), cfg); return; }
  if (m.kind === 'rent') { const lease = await d.one(`SELECT l.*, u.property_id FROM leases l JOIN units u ON u.id=l.unit_id WHERE l.id=?`, +m.lease_id); if (!lease) return;
    const { jid } = await postRent69(d, { lease, amount: +m.amount, fee: +m.fee || 0, feeBy: m.fee_by, method: m.method, ref, test: /^cs_test_/.test(sess.id || ''), src: m.src || 'paylink' });
    await d.run('INSERT INTO payments(processor,status,amount,tenant_id,lease_id,method,ref,journal_id,created,meta) VALUES(?,?,?,?,?,?,?,?,?,?)', 'stripe', 'succeeded', +m.amount, lease.tenant_id, lease.id, m.method, ref, jid, nowISO(), JSON.stringify({ src: 'x69paylink', fee: +m.fee || 0, fee_by: m.fee_by, session: sess.id }));
    if (m.autopay && sess.customer) { const pi = sess.payment_intent || {}; await d.run(`UPDATE ap69 SET status='cancelled', updated=? WHERE tenant_id=? AND status='active'`, nowISO(), lease.tenant_id);
      await d.run('INSERT INTO ap69(tenant_id,lease_id,method,last4,day,amount_mode,status,processor,cust,pm,created,updated,test) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)', lease.tenant_id, lease.id, m.method, '', +m.autopay || 1, 'balance', 'active', 'stripe', sess.customer, pi.payment_method || '', nowISO(), nowISO(), /^cs_test_/.test(sess.id || '') ? 1 : 0); } }
}
